const std = @import("std");
const unscaled = @import("unscaled.zig");
const generic = @import("generic.zig");

const Ctx = struct {
    kind: enum { unscaled, generic },
    u: unscaled.Unscaled = undefined,
    g: *generic.Generic = undefined,
};

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    if (src_fmt < 0 or src_fmt > 9 or dst_fmt < 0 or dst_fmt > 9 or algo < 0 or algo > 2) return null;
    if (src_w < 1 or src_h < 1 or dst_w < 1 or dst_h < 1) return null;
    const ctx = std.heap.c_allocator.create(Ctx) catch return null;
    if (unscaled.init(&ctx.u, src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo)) {
        ctx.kind = .unscaled;
        return @ptrCast(ctx);
    }
    ctx.kind = .generic;
    ctx.g = generic.create(src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo) orelse {
        std.heap.c_allocator.destroy(ctx);
        return null;
    };
    return @ptrCast(ctx);
}

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const ctx: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    switch (ctx.kind) {
        .unscaled => unscaled.process(&ctx.u, src_data, src_stride, dst_data, dst_stride),
        .generic => generic.process(ctx.g, src_data, src_stride, dst_data, dst_stride),
    }
    return 0;
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    if (handle) |ptr| {
        const ctx: *Ctx = @ptrCast(@alignCast(ptr));
        if (ctx.kind == .generic) generic.destroy(ctx.g);
        std.heap.c_allocator.destroy(ctx);
    }
}
EOF
