        c->convert_unscaled = uyvyToYuv422Wrapper;
    if (dstFormat == AV_PIX_FMT_YUV420P &&
        (srcFormat == AV_PIX_FMT_NV24 || srcFormat == AV_PIX_FMT_NV42))
        c->convert_unscaled = nv24ToYuv420Wrapper;
