// RgbTables API ready
// Same-size special-case converters (FFmpeg's convert_unscaled paths).
const std = @import("std");

const YUV420P = 0;
const YUV422P = 1;
const YUV444P = 2;
const NV12 = 3;
const NV21 = 4;
const RGB24 = 5;
const BGR24 = 6;
const RGBA = 7;
const BGRA = 8;
const GRAY8 = 9;

// ───────────────────────── yuv2rgb tables (ff_yuv2rgb_c_init_tables, srcRange=0) ─────────────────────────
//
// The C code builds a clipped luma ramp y_table[i] = clip_u8((yb0 + i*cy + 0x8000) >> 16) and per-chroma
// pointer offsets into it.  r[Y] = y_table[yoffs + Y + roff(V)] etc.  We keep the closed form.
pub const RgbTables = struct {
    cy: i64 = 0,
    crv: i64 = 0,
    cbu: i64 = 0,
    cgu: i64 = 0,
    cgv: i64 = 0,
    yb0: i64 = 0, // value of yb at table index 0
    // precomputed per chroma value (0..255): additive i32 terms t such that
    // channel = clip_u8((Y*cy + t) >> 16)
    tr: [256]i32 = undefined,
    tgu: [256]i32 = undefined, // includes base
    tgv: [256]i32 = undefined, // pure offset*cy (no base)
    tb: [256]i32 = undefined,
};

const YOFFS: i64 = 326 + 512;

fn tabOff(inc: i64, i: i64) i64 {
    const c = std.math.clamp(i, 0, 255);
    return -(inc >> 9) + ((c * inc) >> 16);
}

pub fn initRgbTables(t: *RgbTables, dst_fmt: c_int) void {
    _ = dst_fmt; // byte values identical for RGB24/BGR24/RGBA/BGRA
    const contrast: i64 = 1 << 16;
    const saturation: i64 = 1 << 16;
    var crv: i64 = 104597;
    var cbu: i64 = 132201;
    var cgu: i64 = -25675;
    var cgv: i64 = -53279;
    var cy: i64 = 1 << 16;
    var oy: i64 = 0;
    cy = @divTrunc(cy * 255, 219);
    oy = 16 << 16;
    cy = (cy * contrast) >> 16;
    crv = (crv * contrast * saturation) >> 32;
    cbu = (cbu * contrast * saturation) >> 32;
    cgu = (cgu * contrast * saturation) >> 32;
    cgv = (cgv * contrast * saturation) >> 32;
    const cyd = @max(cy, 1);
    crv = @divTrunc(crv * 65536 + 0x8000, cyd);
    cbu = @divTrunc(cbu * 65536 + 0x8000, cyd);
    cgu = @divTrunc(cgu * 65536 + 0x8000, cyd);
    cgv = @divTrunc(cgv * 65536 + 0x8000, cyd);
    t.cy = cy;
    t.crv = crv;
    t.cbu = cbu;
    t.cgu = cgu;
    t.cgv = cgv;
    t.yb0 = -(384 << 16) - 512 * cy - oy;
    const base = YOFFS * cy + t.yb0 + 0x8000;
    var i: i64 = 0;
    while (i < 256) : (i += 1) {
        const k: usize = @intCast(i);
        t.tr[k] = @intCast(base + tabOff(crv, i) * cy);
        t.tgu[k] = @intCast(base + tabOff(cgu, i) * cy);
        t.tgv[k] = @intCast(tabOff(cgv, i) * cy);
        t.tb[k] = @intCast(base + tabOff(cbu, i) * cy);
    }
}

inline fn clipU8(x: i64) u8 {
    return @intCast(std.math.clamp(x, 0, 255));
}

/// {R,G,B} exactly as the r[Y]/g[Y]/b[Y] table lookups (U,V clipped to 0..255 like the table headroom).
pub fn tableRGB(t: *const RgbTables, y: i32, u: i32, v: i32) [3]u8 {
    const Y: i64 = y;
    const ri = YOFFS + Y + tabOff(t.crv, v);
    const gi = YOFFS + Y + tabOff(t.cgu, u) + tabOff(t.cgv, v);
    const bi = YOFFS + Y + tabOff(t.cbu, u);
    return .{
        clipU8((t.yb0 + ri * t.cy + 0x8000) >> 16),
        clipU8((t.yb0 + gi * t.cy + 0x8000) >> 16),
        clipU8((t.yb0 + bi * t.cy + 0x8000) >> 16),
    };
}

// ───────────────────────── context ─────────────────────────

const Kind = enum { yuv2rgb, luma_copy, gray2yuv, p2nv, nv2p, rgb2rgb, bgr2yuv };

pub const Unscaled = struct {
    w: c_int = 0,
    h: c_int = 0,
    src_fmt: c_int = 0,
    dst_fmt: c_int = 0,
    kind: Kind = .luma_copy,
    tabs: RgbTables = .{},
};

fn isRgb(f: c_int) bool {
    return f >= RGB24 and f <= BGRA;
}

pub fn init(u: *Unscaled, src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) bool {
    _ = algo;
    if (src_w != dst_w or src_h != dst_h) return false;
    u.* = .{ .w = src_w, .h = src_h, .src_fmt = src_fmt, .dst_fmt = dst_fmt };
    if ((src_fmt == YUV420P or src_fmt == YUV422P) and isRgb(dst_fmt)) {
        if ((src_h & 1) != 0 or (src_w & 1) != 0) return false;
        u.kind = .yuv2rgb;
        initRgbTables(&u.tabs, dst_fmt);
        return true;
    }
    if (src_fmt == YUV420P and dst_fmt == GRAY8) {
        u.kind = .luma_copy;
        return true;
    }
    if (src_fmt == GRAY8 and dst_fmt == YUV420P) {
        u.kind = .gray2yuv;
        return true;
    }
    if (src_fmt == YUV420P and (dst_fmt == NV12 or dst_fmt == NV21)) {
        u.kind = .p2nv;
        return true;
    }
    if ((src_fmt == NV12 or src_fmt == NV21) and dst_fmt == YUV420P) {
        u.kind = .nv2p;
        return true;
    }
    if (isRgb(src_fmt) and isRgb(dst_fmt) and src_fmt != dst_fmt) {
        u.kind = .rgb2rgb;
        return true;
    }
    if (src_fmt == BGR24 and dst_fmt == YUV420P and (src_w & 1) == 0 and (src_h & 1) == 0) {
        u.kind = .bgr2yuv;
        return true;
    }
    return false;
}

inline fn rowc(p: [*]const u8, stride: c_int, y: usize) [*]const u8 {
    const off: isize = @as(isize, stride) * @as(isize, @intCast(y));
    return @ptrFromInt(@as(usize, @bitCast(@as(isize, @bitCast(@intFromPtr(p))) + off)));
}
inline fn rowm(p: [*]u8, stride: c_int, y: usize) [*]u8 {
    const off: isize = @as(isize, stride) * @as(isize, @intCast(y));
    return @ptrFromInt(@as(usize, @bitCast(@as(isize, @bitCast(@intFromPtr(p))) + off)));
}

pub fn process(u: *const Unscaled, src: [*]const ?[*]const u8, src_stride: [*]const c_int, dst: [*]const ?[*]u8, dst_stride: [*]const c_int) void {
    const w: usize = @intCast(u.w);
    const h: usize = @intCast(u.h);
    switch (u.kind) {
        .yuv2rgb => yuv2rgb(u, src, src_stride, dst, dst_stride, w, h),
        .luma_copy => copyPlane(src[0].?, src_stride[0], dst[0].?, dst_stride[0], w, h),
        .gray2yuv => {
            copyPlane(src[0].?, src_stride[0], dst[0].?, dst_stride[0], w, h);
            const cw = (w + 1) >> 1;
            const ch = (h + 1) >> 1;
            for (1..3) |p| {
                if (dst[p]) |d| {
                    for (0..ch) |y| @memset(rowm(d, dst_stride[p], y)[0..cw], 128);
                }
            }
        },
        .p2nv => {
            copyPlane(src[0].?, src_stride[0], dst[0].?, dst_stride[0], w, h);
            const cw = (w + 1) >> 1;
            const ch = (h + 1) >> 1;
            const a: usize = if (u.dst_fmt == NV12) 1 else 2;
            const b: usize = 3 - a;
            for (0..ch) |y| interleave(rowc(src[a].?, src_stride[a], y), rowc(src[b].?, src_stride[b], y), rowm(dst[1].?, dst_stride[1], y), cw);
        },
        .nv2p => {
            copyPlane(src[0].?, src_stride[0], dst[0].?, dst_stride[0], w, h);
            const cw = (w + 1) >> 1;
            const ch = (h + 1) >> 1;
            const a: usize = if (u.src_fmt == NV12) 1 else 2;
            const b: usize = 3 - a;
            for (0..ch) |y| deinterleave(rowc(src[1].?, src_stride[1], y), rowm(dst[a].?, dst_stride[a], y), rowm(dst[b].?, dst_stride[b], y), cw);
        },
        .rgb2rgb => rgb2rgb(u, src[0].?, src_stride[0], dst[0].?, dst_stride[0], w, h),
        .bgr2yuv => bgr2yuv(src[0].?, src_stride[0], dst, dst_stride, w, h),
    }
}

fn copyPlane(s: [*]const u8, ss: c_int, d: [*]u8, ds: c_int, w: usize, h: usize) void {
    for (0..h) |y| @memcpy(rowm(d, ds, y)[0..w], rowc(s, ss, y)[0..w]);
}

fn interleave(a: [*]const u8, b: [*]const u8, d: [*]u8, n: usize) void {
    var i: usize = 0;
    while (i + 32 <= n) : (i += 32) {
        const va: @Vector(32, u8) = a[i..][0..32].*;
        const vb: @Vector(32, u8) = b[i..][0..32].*;
        const m = comptime blk: {
            var mm: [64]i32 = undefined;
            for (0..32) |k| {
                mm[2 * k] = @intCast(k);
                mm[2 * k + 1] = ~@as(i32, @intCast(k));
            }
            break :blk mm;
        };
        d[2 * i ..][0..64].* = @shuffle(u8, va, vb, m);
    }
    while (i < n) : (i += 1) {
        d[2 * i] = a[i];
        d[2 * i + 1] = b[i];
    }
}

fn deinterleave(s: [*]const u8, a: [*]u8, b: [*]u8, n: usize) void {
    var i: usize = 0;
    while (i + 32 <= n) : (i += 32) {
        const v: @Vector(64, u8) = s[2 * i ..][0..64].*;
        const ma = comptime blk: {
            var mm: [32]i32 = undefined;
            for (0..32) |k| mm[k] = @intCast(2 * k);
            break :blk mm;
        };
        const mb = comptime blk: {
            var mm: [32]i32 = undefined;
            for (0..32) |k| mm[k] = @intCast(2 * k + 1);
            break :blk mm;
        };
        a[i..][0..32].* = @shuffle(u8, v, undefined, ma);
        b[i..][0..32].* = @shuffle(u8, v, undefined, mb);
    }
    while (i < n) : (i += 1) {
        a[i] = s[2 * i];
        b[i] = s[2 * i + 1];
    }
}

// ───────────────────────── RGB <-> RGB ─────────────────────────

fn bpp(f: c_int) usize {
    return if (f == RGB24 or f == BGR24) 3 else 4;
}
// byte position of R in format (B is 2-pos)
fn rpos(f: c_int) usize {
    return if (f == RGB24 or f == RGBA) 0 else 2;
}

fn rgbMask(comptime sb: usize, comptime sr: usize, comptime db: usize, comptime dr: usize, comptime n: usize) [n * db]i32 {
    var m: [n * db]i32 = undefined;
    for (0..n) |p| {
        m[p * db + dr] = @intCast(p * sb + sr);
        m[p * db + 1] = @intCast(p * sb + 1);
        m[p * db + (2 - dr)] = @intCast(p * sb + (2 - sr));
        if (db == 4) {
            m[p * db + 3] = if (sb == 4) @intCast(p * sb + 3) else -1; // ~0 -> b[0] = 255
        }
    }
    return m;
}

fn rgbRow(comptime sb: usize, comptime sr: usize, comptime db: usize, comptime dr: usize, s: [*]const u8, d: [*]u8, w: usize) void {
    const N = 16;
    const m = comptime rgbMask(sb, sr, db, dr, N);
    const ff: @Vector(N * sb, u8) = @splat(255);
    var x: usize = 0;
    while (x + N <= w) : (x += N) {
        const v: @Vector(N * sb, u8) = s[x * sb ..][0 .. N * sb].*;
        d[x * db ..][0 .. N * db].* = @shuffle(u8, v, ff, m);
    }
    while (x < w) : (x += 1) {
        const sp = s + x * sb;
        const dp = d + x * db;
        dp[dr] = sp[sr];
        dp[1] = sp[1];
        dp[2 - dr] = sp[2 - sr];
        if (db == 4) dp[3] = if (sb == 4) sp[3] else 255;
    }
}

fn rgb2rgb(u: *const Unscaled, s: [*]const u8, ss: c_int, d: [*]u8, ds: c_int, w: usize, h: usize) void {
    const sb = bpp(u.src_fmt);
    const db = bpp(u.dst_fmt);
    const sr = rpos(u.src_fmt);
    const dr = rpos(u.dst_fmt);
    inline for (.{ 3, 4 }) |SB| inline for (.{ 3, 4 }) |DB| inline for (.{ 0, 2 }) |SR| inline for (.{ 0, 2 }) |DR| {
        if (sb == SB and db == DB and sr == SR and dr == DR) {
            for (0..h) |y| rgbRow(SB, SR, DB, DR, rowc(s, ss, y), rowm(d, ds, y), w);
            return;
        }
    };
}

// ───────────────────────── BGR24 -> YUV420P (rgb24toyv12_c) ─────────────────────────

const RY = 8414;
const GY = 16519;
const BY = 3208;
const RU = -4865;
const GU = -9528;
const BU = 14392;
const RV = 14392;
const GV = -12061;
const BV = -2332;

fn bgr2yuv(s: [*]const u8, ss: c_int, dst: [*]const ?[*]u8, ds: [*]const c_int, w: usize, h: usize) void {
    const cw = w >> 1;
    var y: usize = 0;
    while (y < h) : (y += 2) {
        const s1 = rowc(s, ss, y);
        const s2 = rowc(s, ss, y + 1);
        const y1 = rowm(dst[0].?, ds[0], y);
        const y2 = rowm(dst[0].?, ds[0], y + 1);
        const ud = rowm(dst[1].?, ds[1], y >> 1);
        const vd = rowm(dst[2].?, ds[2], y >> 1);
        for (0..cw) |i| {
            const b11: i32 = s1[6 * i + 0];
            const g11: i32 = s1[6 * i + 1];
            const r11: i32 = s1[6 * i + 2];
            const b12: i32 = s1[6 * i + 3];
            const g12: i32 = s1[6 * i + 4];
            const r12: i32 = s1[6 * i + 5];
            const b21: i32 = s2[6 * i + 0];
            const g21: i32 = s2[6 * i + 1];
            const r21: i32 = s2[6 * i + 2];
            const b22: i32 = s2[6 * i + 3];
            const g22: i32 = s2[6 * i + 4];
            const r22: i32 = s2[6 * i + 5];
            y1[2 * i] = @truncate(@as(u32, @bitCast(((RY * r11 + GY * g11 + BY * b11) >> 15) + 16)));
            y1[2 * i + 1] = @truncate(@as(u32, @bitCast(((RY * r12 + GY * g12 + BY * b12) >> 15) + 16)));
            y2[2 * i] = @truncate(@as(u32, @bitCast(((RY * r21 + GY * g21 + BY * b21) >> 15) + 16)));
            y2[2 * i + 1] = @truncate(@as(u32, @bitCast(((RY * r22 + GY * g22 + BY * b22) >> 15) + 16)));
            const bx = (b11 + b12 + b21 + b22) >> 2;
            const gx = (g11 + g12 + g21 + g22) >> 2;
            const rx = (r11 + r12 + r21 + r22) >> 2;
            ud[i] = @truncate(@as(u32, @bitCast(((RU * rx + GU * gx + BU * bx) >> 15) + 128)));
            vd[i] = @truncate(@as(u32, @bitCast(((RV * rx + GV * gx + BV * bx) >> 15) + 128)));
        }
    }
}

// ───────────────────────── YUV -> RGB ─────────────────────────

fn yuv2rgb(u: *const Unscaled, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int, w: usize, h: usize) void {
    const is422 = u.src_fmt == YUV422P;
    switch (u.dst_fmt) {
        RGB24 => yuv2rgbT(3, 0, is422, &u.tabs, src, ss, dst, ds, w, h),
        BGR24 => yuv2rgbT(3, 2, is422, &u.tabs, src, ss, dst, ds, w, h),
        RGBA => yuv2rgbT(4, 0, is422, &u.tabs, src, ss, dst, ds, w, h),
        else => yuv2rgbT(4, 2, is422, &u.tabs, src, ss, dst, ds, w, h),
    }
}

inline fn clip16(x: i32) u8 {
    return @intCast(std.math.clamp(x >> 16, 0, 255));
}

fn yuv2rgbRowScalar(comptime db: usize, comptime dr: usize, t: *const RgbTables, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, d: [*]u8, x0: usize, w: usize) void {
    const cy: i32 = @intCast(t.cy);
    var x = x0;
    while (x < w) : (x += 2) {
        const U = pu[x >> 1];
        const V = pv[x >> 1];
        const tr = t.tr[V];
        const tg = t.tgu[U] + t.tgv[V];
        const tb = t.tb[U];
        inline for (0..2) |k| {
            const yl = @as(i32, py[x + k]) * cy;
            const dp = d + (x + k) * db;
            dp[dr] = clip16(yl + tr);
            dp[1] = clip16(yl + tg);
            dp[2 - dr] = clip16(yl + tb);
            if (db == 4) dp[3] = 255;
        }
    }
}

fn yuv2rgbT(comptime db: usize, comptime dr: usize, is422: bool, t: *const RgbTables, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int, w: usize, h: usize) void {
    for (0..h) |y| {
        const cyr = if (is422) y else y >> 1;
        yuv2rgbRowScalar(db, dr, t, rowc(src[0].?, ss[0], y), rowc(src[1].?, ss[1], cyr), rowc(src[2].?, ss[2], cyr), rowm(dst[0].?, ds[0], y), 0, w);
    }
}

