// Generic scaler pipeline modelled on FFmpeg's swscale():
// input -> 15-bit horizontal scale -> vertical scale -> output writer.
const std = @import("std");
const alloc = std.heap.c_allocator;
const simd = @import("simd.zig");

pub const Kind = enum { yuv, nv, rgb, gray };

pub const Fmt = struct {
    kind: Kind,
    hsub: u5 = 0,
    vsub: u5 = 0,
    swap_uv: bool = false,
    bpp: u3 = 1,
    ri: u3 = 0,
    gi: u3 = 1,
    bi: u3 = 2,
    alpha: bool = false,
};

pub fn fmtInfo(f: c_int) Fmt {
    return switch (f) {
        0 => .{ .kind = .yuv, .hsub = 1, .vsub = 1 },
        1 => .{ .kind = .yuv, .hsub = 1, .vsub = 0 },
        2 => .{ .kind = .yuv },
        3 => .{ .kind = .nv, .hsub = 1, .vsub = 1 },
        4 => .{ .kind = .nv, .hsub = 1, .vsub = 1, .swap_uv = true },
        5 => .{ .kind = .rgb, .bpp = 3, .ri = 0, .gi = 1, .bi = 2 },
        6 => .{ .kind = .rgb, .bpp = 3, .ri = 2, .gi = 1, .bi = 0 },
        7 => .{ .kind = .rgb, .bpp = 4, .ri = 0, .gi = 1, .bi = 2, .alpha = true },
        8 => .{ .kind = .rgb, .bpp = 4, .ri = 2, .gi = 1, .bi = 0, .alpha = true },
        else => .{ .kind = .gray },
    };
}

const SWS_POINT = 0x10;
const SWS_BILINEAR = 2;
const SWS_BICUBIC = 4;

pub const Filter = struct {
    size: i32,
    pos: []i32,
    coef: []i16,
};

fn avLog2(v: i64) i64 {
    if (v <= 0) return 0;
    return 63 - @as(i64, @clz(@as(u64, @intCast(v))));
}

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

fn iabs(a: i64) i64 {
    return if (a < 0) -a else a;
}

// Port of utils.c initFilter (filterAlign 1, no src/dst vectors).
fn initFilter(xInc: i64, srcW: i32, dstW: i32, one: i64, flags: u32, srcPos: i64, dstPos: i64) !Filter {
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(avLog2(@divTrunc(srcW, dstW)), 8));
    const dW: usize = @intCast(dstW);
    var pos = try alloc.alloc(i32, dW + 3);
    var filterSize: i64 = 0;
    var filter: []i64 = undefined;

    if (iabs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dW);
        for (0..dW) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (flags & SWS_POINT != 0) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dW);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..dW) |i| {
            const xx = (xDstInSrc - ((filterSize - 1) << 15) + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i64 = if (flags & SWS_BICUBIC != 0) 4 else 2;
        if (xInc <= 1 << 16) {
            filterSize = 1 + sizeFactor;
        } else {
            filterSize = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        filterSize = @min(filterSize, srcW - 2);
        filterSize = @max(filterSize, 1);
        const fs: usize = @intCast(filterSize);
        filter = try alloc.alloc(i64, dW * fs);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        for (0..dW) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (filterSize - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..fs) |j| {
                var d: i64 = iabs(xx * (1 << 17) - xDstInSrc) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (flags & SWS_BICUBIC != 0) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(@as(f64, 0.6) * @as(f64, 1 << 24));
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * fs + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }
    defer alloc.free(filter);

    const filter2Size = filterSize;
    const f2s: usize = @intCast(filter2Size);
    // filter2 == filter (no src/dst vectors)
    var filter2 = filter;

    // step1: find size and shift left
    var minFilterSize: i64 = 0;
    const cutoff_lim: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    var ii: i64 = @as(i64, dstW) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: i64 = filter2Size;
        var cutOff: i64 = 0;
        var j: usize = 0;
        while (j < f2s) : (j += 1) {
            cutOff += iabs(filter2[i * f2s]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoff_lim) break;
            if (i < dW - 1 and pos[i] >= pos[i + 1]) break;
            var k: usize = 1;
            while (k < f2s) : (k += 1) filter2[i * f2s + k - 1] = filter2[i * f2s + k];
            filter2[i * f2s + k - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var jj: i64 = filter2Size - 1;
        while (jj > 0) : (jj -= 1) {
            cutOff += iabs(filter2[i * f2s + @as(usize, @intCast(jj))]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoff_lim) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }

    const outSize: i64 = minFilterSize;
    const os: usize = @intCast(outSize);
    var f3 = try alloc.alloc(i64, dW * os);
    defer alloc.free(f3);
    for (0..dW) |i| {
        for (0..os) |j| {
            f3[i * os + j] = if (j >= f2s) 0 else filter2[i * f2s + j];
        }
    }

    // fix borders
    for (0..dW) |i| {
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < os) : (j += 1) {
                const left: usize = @intCast(@max(@as(i64, @intCast(j)) + pos[i], 0));
                f3[i * os + left] += f3[i * os + j];
                f3[i * os + j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + outSize > srcW) {
            const shift: i64 = pos[i] + @min(outSize - srcW, 0);
            var acc: i64 = 0;
            var jj: i64 = outSize - 1;
            while (jj >= 0) : (jj -= 1) {
                const j: usize = @intCast(jj);
                if (pos[i] + jj >= srcW) {
                    acc += f3[i * os + j];
                    f3[i * os + j] = 0;
                }
            }
            jj = outSize - 1;
            while (jj >= 0) : (jj -= 1) {
                const j: usize = @intCast(jj);
                if (jj < shift) {
                    f3[i * os + j] = 0;
                } else {
                    f3[i * os + j] = f3[i * os + @as(usize, @intCast(jj - shift))];
                }
            }
            pos[i] -= @intCast(shift);
            f3[i * os + @as(usize, @intCast(srcW - 1 - pos[i]))] += acc;
        }
    }

    var coef = try alloc.alloc(i16, os * (dW + 3));
    @memset(coef, 0);
    for (0..dW) |i| {
        var sum: i64 = 0;
        for (0..os) |j| sum += f3[i * os + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        var err: i64 = 0;
        for (0..os) |j| {
            const v = f3[i * os + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * os + j] = @truncate(intV);
            err = v - intV * sum;
        }
    }
    pos[dW] = pos[dW - 1];
    pos[dW + 1] = pos[dW - 1];
    pos[dW + 2] = pos[dW - 1];
    return .{ .size = @intCast(outSize), .pos = pos, .coef = coef };
}

pub const Generic = struct {
    src_w: i32,
    src_h: i32,
    dst_w: i32,
    dst_h: i32,
    sf: Fmt,
    df: Fmt,
    src_fmt: c_int,
    dst_fmt: c_int,
    chr_src_w: i32,
    chr_src_h: i32,
    chr_dst_w: i32,
    chr_dst_h: i32,
    chr_src_hsub: u5,
    chr_src_vsub: u5,
    chr_dst_hsub: u5,
    chr_dst_vsub: u5,
    full_chr: bool,
    need_alpha: bool,
    needs_hc: bool,
    hl: Filter,
    hc: Filter,
    vl: Filter,
    vc: Filter,
    lum: []i16,
    alp: []i16,
    cu: []i16,
    cv: []i16,
    lum_stride: usize,
    chr_stride: usize,
    lum_need: []bool,
    chr_need: []bool,
    tmp: []i16,
    tmp2: []i16,
    tmp3: []i16,
    tmp8a: []u8,
    tmp8b: []u8,
    // rgb2yuv
    ry: i32,
    gy: i32,
    by: i32,
    ru: i32,
    gu: i32,
    bu: i32,
    rv: i32,
    gv: i32,
    bv: i32,
    // yuv2rgb (full)
    y_off: i32,
    y_coef: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,
    // yuv2rgb tables (half chroma)
    ytab: [2048]u8,
    t_rv: [256]i32,
    t_gu: [256]i32,
    t_gv: [256]i32,
    t_bu: [256]i32,
};

fn roundToInt16(f: i64) i32 {
    const r: i64 = (f + (1 << 15)) >> 16;
    const u: u16 = @truncate(@as(u64, @bitCast(r)));
    return @as(i16, @bitCast(u));
}

fn clipU8(v: i64) i64 {
    return if (v < 0) 0 else if (v > 255) 255 else v;
}

fn initColor(g: *Generic) void {
    // rgb2yuv default-table constants (fill_rgb2yuv_table special case)
    const S: f64 = 32768.0;
    g.by = @intFromFloat(0.114 * 219.0 / 255.0 * S + 0.5);
    g.bv = -@as(i32, @intFromFloat(0.081 * 224.0 / 255.0 * S + 0.5));
    g.bu = @intFromFloat(0.500 * 224.0 / 255.0 * S + 0.5);
    g.gy = @intFromFloat(0.587 * 219.0 / 255.0 * S + 0.5);
    g.gv = -@as(i32, @intFromFloat(0.419 * 224.0 / 255.0 * S + 0.5));
    g.gu = -@as(i32, @intFromFloat(0.331 * 224.0 / 255.0 * S + 0.5));
    g.ry = @intFromFloat(0.299 * 219.0 / 255.0 * S + 0.5);
    g.rv = @intFromFloat(0.500 * 224.0 / 255.0 * S + 0.5);
    g.ru = -@as(i32, @intFromFloat(0.169 * 224.0 / 255.0 * S + 0.5));

    // ff_yuv2rgb_c_init_tables, srcRange = 0
    var crv: i64 = 104597;
    var cbu: i64 = 132201;
    var cgu: i64 = -25675;
    var cgv: i64 = -53279;
    var cy: i64 = 1 << 16;
    var oy: i64 = 0;
    cy = @divTrunc(cy * 255, 219);
    oy = 16 << 16;
    const contrast: i64 = 1 << 16;
    const saturation: i64 = 1 << 16;
    cy = (cy * contrast) >> 16;
    crv = (crv * contrast * saturation) >> 32;
    cbu = (cbu * contrast * saturation) >> 32;
    cgu = (cgu * contrast * saturation) >> 32;
    cgv = (cgv * contrast * saturation) >> 32;
    g.y_coef = roundToInt16(cy * (1 << 13));
    g.y_off = roundToInt16(oy * (1 << 9));
    g.v2r = roundToInt16(crv * (1 << 13));
    g.v2g = roundToInt16(cgv * (1 << 13));
    g.u2g = roundToInt16(cgu * (1 << 13));
    g.u2b = roundToInt16(cbu * (1 << 13));
    const cyd = @max(cy, 1);
    crv = @divTrunc(crv * (1 << 16) + 0x8000, cyd);
    cbu = @divTrunc(cbu * (1 << 16) + 0x8000, cyd);
    cgu = @divTrunc(cgu * (1 << 16) + 0x8000, cyd);
    cgv = @divTrunc(cgv * (1 << 16) + 0x8000, cyd);
    var yb: i64 = -(384 << 16) - 512 * cy - oy;
    for (0..2048) |i| {
        g.ytab[i] = @intCast(clipU8((yb + 0x8000) >> 16));
        yb += cy;
    }
    const yoffs: i64 = 326 + 512;
    for (0..256) |i| {
        const ci: i64 = @intCast(i);
        g.t_rv[i] = @intCast(yoffs - (crv >> 9) + ((ci * crv) >> 16));
        g.t_gu[i] = @intCast(yoffs - (cgu >> 9) + ((ci * cgu) >> 16));
        g.t_bu[i] = @intCast(yoffs - (cbu >> 9) + ((ci * cbu) >> 16));
        g.t_gv[i] = @intCast(-(cgv >> 9) + ((ci * cgv) >> 16));
    }
}

pub fn create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*Generic {
    return createImpl(src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo) catch null;
}

fn ceilShift(a: i32, s: u5) i32 {
    return -((-a) >> s);
}

fn createImpl(srcW: i32, srcH: i32, src_fmt: c_int, dstW: i32, dstH: i32, dst_fmt: c_int, algo: c_int) !*Generic {
    const g = try alloc.create(Generic);
    errdefer alloc.destroy(g);
    g.src_w = srcW;
    g.src_h = srcH;
    g.dst_w = dstW;
    g.dst_h = dstH;
    g.src_fmt = src_fmt;
    g.dst_fmt = dst_fmt;
    const sf = fmtInfo(src_fmt);
    const df = fmtInfo(dst_fmt);
    g.sf = sf;
    g.df = df;
    const flags: u32 = switch (algo) {
        0 => SWS_POINT,
        1 => SWS_BILINEAR,
        else => SWS_BICUBIC,
    };
    initColor(g);

    const lumXInc: i64 = @divTrunc((@as(i64, srcW) << 16) + (dstW >> 1), dstW);
    const lumYInc: i64 = @divTrunc((@as(i64, srcH) << 16) + (dstH >> 1), dstH);

    var csh: u5 = sf.hsub;
    const csv: u5 = sf.vsub;
    var cdh: u5 = df.hsub;
    const cdv: u5 = df.vsub;
    var full = false;
    if (df.kind == .rgb) {
        if (dstW & 1 != 0) full = true;
        if (csh == 0 and csv == 0) full = true;
        if (!full) cdh = 1;
    }
    if (sf.kind == .rgb and ((dstW >> cdh) <= (srcW >> 1))) csh = 1;
    g.full_chr = full;
    g.chr_src_hsub = csh;
    g.chr_src_vsub = csv;
    g.chr_dst_hsub = cdh;
    g.chr_dst_vsub = cdv;
    g.chr_src_w = ceilShift(srcW, csh);
    g.chr_src_h = ceilShift(srcH, csv);
    g.chr_dst_w = ceilShift(dstW, cdh);
    g.chr_dst_h = ceilShift(dstH, cdv);
    g.need_alpha = sf.alpha and df.alpha;
    g.needs_hc = !(sf.kind == .gray or df.kind == .gray);

    const chrXInc: i64 = @divTrunc((@as(i64, g.chr_src_w) << 16) + (g.chr_dst_w >> 1), g.chr_dst_w);
    const chrYInc: i64 = @divTrunc((@as(i64, g.chr_src_h) << 16) + (g.chr_dst_h >> 1), g.chr_dst_h);

    g.hl = try initFilter(lumXInc, srcW, dstW, 1 << 14, flags, 128, 128);
    g.hc = try initFilter(chrXInc, g.chr_src_w, g.chr_dst_w, 1 << 14, flags, 128, 128);
    g.vl = try initFilter(lumYInc, srcH, dstH, 1 << 12, flags, 128, 128);
    g.vc = try initFilter(chrYInc, g.chr_src_h, g.chr_dst_h, 1 << 12, flags, 128, 128);

    const sh: usize = @intCast(srcH);
    const csh_n: usize = @intCast(g.chr_src_h);
    g.lum_stride = (@as(usize, @intCast(dstW)) + 31) & ~@as(usize, 15);
    g.chr_stride = (@as(usize, @intCast(g.chr_dst_w)) + 31) & ~@as(usize, 15);
    g.lum = try alloc.alloc(i16, g.lum_stride * sh);
    g.alp = if (g.need_alpha) try alloc.alloc(i16, g.lum_stride * sh) else &[_]i16{};
    g.cu = try alloc.alloc(i16, g.chr_stride * csh_n);
    g.cv = try alloc.alloc(i16, g.chr_stride * csh_n);
    if (!g.needs_hc) {
        @memset(g.cu, 1 << 14);
        @memset(g.cv, 1 << 14);
    }
    g.lum_need = try alloc.alloc(bool, sh);
    g.chr_need = try alloc.alloc(bool, csh_n);
    @memset(g.lum_need, false);
    @memset(g.chr_need, false);
    markNeeded(&g.vl, dstH, srcH, g.lum_need);
    if (df.kind != .gray) markNeeded(&g.vc, g.chr_dst_h, g.chr_src_h, g.chr_need);
    const tw: usize = @as(usize, @intCast(srcW)) * 2 + 64;
    g.tmp = try alloc.alloc(i16, tw);
    g.tmp2 = try alloc.alloc(i16, tw);
    g.tmp3 = try alloc.alloc(i16, tw);
    g.tmp8a = try alloc.alloc(u8, tw);
    g.tmp8b = try alloc.alloc(u8, tw);
    @memset(g.tmp, 0);
    @memset(g.tmp2, 0);
    @memset(g.tmp3, 0);
    @memset(g.tmp8a, 0);
    @memset(g.tmp8b, 0);
    return g;
}

fn markNeeded(f: *const Filter, dh: i32, sh: i32, need: []bool) void {
    const fs: usize = @intCast(f.size);
    for (0..@intCast(dh)) |y| {
        for (0..fs) |j| {
            const l = f.pos[y] + @as(i32, @intCast(j));
            if (l >= 0 and l < sh and f.coef[y * fs + j] != 0) need[@intCast(l)] = true;
        }
        // first line is always referenced
        const l0 = @min(@max(f.pos[y], 0), sh - 1);
        need[@intCast(l0)] = true;
    }
}

pub fn destroy(g: *Generic) void {
    for ([_]*Filter{ &g.hl, &g.hc, &g.vl, &g.vc }) |f| {
        alloc.free(f.pos);
        alloc.free(f.coef);
    }
    alloc.free(g.lum);
    if (g.need_alpha) alloc.free(g.alp);
    alloc.free(g.cu);
    alloc.free(g.cv);
    alloc.free(g.lum_need);
    alloc.free(g.chr_need);
    alloc.free(g.tmp);
    alloc.free(g.tmp2);
    alloc.free(g.tmp3);
    alloc.free(g.tmp8a);
    alloc.free(g.tmp8b);
    alloc.destroy(g);
}

inline fn rowPtr(p: ?[*]const u8, stride: c_int, y: i32) [*]const u8 {
    const base = p.?;
    const off: isize = @as(isize, stride) * @as(isize, y);
    return @ptrFromInt(@as(usize, @bitCast(@as(isize, @bitCast(@intFromPtr(base))) + off)));
}

inline fn rowPtrMut(p: ?[*]u8, stride: c_int, y: i32) [*]u8 {
    const base = p.?;
    const off: isize = @as(isize, stride) * @as(isize, y);
    return @ptrFromInt(@as(usize, @bitCast(@as(isize, @bitCast(@intFromPtr(base))) + off)));
}

pub fn process(g: *Generic, src: [*]const ?[*]const u8, src_stride: [*]const c_int, dst: [*]const ?[*]u8, dst_stride: [*]const c_int) void {
    const sf = g.sf;
    const dW: usize = @intCast(g.dst_w);
    const cdW: usize = @intCast(g.chr_dst_w);
    const sW: usize = @intCast(g.src_w);
    const csW: usize = @intCast(g.chr_src_w);

    // ---- horizontal luma (+alpha)
    for (0..@intCast(g.src_h)) |yu| {
        if (!g.lum_need[yu]) continue;
        const y: i32 = @intCast(yu);
        const out = g.lum[yu * g.lum_stride ..][0..dW];
        switch (sf.kind) {
            .rgb => {
                const row = rowPtr(src[0], src_stride[0], y);
                simd.rgbToY(row, g.tmp.ptr, sW, sf.bpp, sf.ri, sf.gi, sf.bi, g.ry, g.gy, g.by);
                simd.hscale16(out.ptr, dW, g.tmp.ptr, &g.hl);
                if (g.need_alpha) {
                    simd.rgbaToA(row, g.tmp.ptr, sW);
                    simd.hscale16(g.alp[yu * g.lum_stride ..].ptr, dW, g.tmp.ptr, &g.hl);
                }
            },
            else => {
                const row = rowPtr(src[0], src_stride[0], y);
                simd.hscale8(out.ptr, dW, row, &g.hl);
            },
        }
    }
    // ---- horizontal chroma
    if (g.needs_hc) {
        for (0..@intCast(g.chr_src_h)) |yu| {
            if (!g.chr_need[yu]) continue;
            const y: i32 = @intCast(yu);
            const ou = g.cu[yu * g.chr_stride ..].ptr;
            const ov = g.cv[yu * g.chr_stride ..].ptr;
            switch (sf.kind) {
                .rgb => {
                    const row = rowPtr(src[0], src_stride[0], y);
                    if (g.chr_src_hsub == 1) {
                        simd.rgbToUVHalf(row, g.tmp2.ptr, g.tmp3.ptr, csW, sf.bpp, sf.ri, sf.gi, sf.bi, g);
                    } else {
                        simd.rgbToUV(row, g.tmp2.ptr, g.tmp3.ptr, sW, sf.bpp, sf.ri, sf.gi, sf.bi, g);
                    }
                    simd.hscale16(ou, cdW, g.tmp2.ptr, &g.hc);
                    simd.hscale16(ov, cdW, g.tmp3.ptr, &g.hc);
                },
                .yuv => {
                    simd.hscale8(ou, cdW, rowPtr(src[1], src_stride[1], y), &g.hc);
                    simd.hscale8(ov, cdW, rowPtr(src[2], src_stride[2], y), &g.hc);
                },
                .nv => {
                    const row = rowPtr(src[1], src_stride[1], y);
                    const a = if (sf.swap_uv) g.tmp8b else g.tmp8a;
                    const b = if (sf.swap_uv) g.tmp8a else g.tmp8b;
                    for (0..csW) |i| {
                        a[i] = row[2 * i];
                        b[i] = row[2 * i + 1];
                    }
                    simd.hscale8(ou, cdW, g.tmp8a.ptr, &g.hc);
                    simd.hscale8(ov, cdW, g.tmp8b.ptr, &g.hc);
                },
                .gray => {},
            }
        }
    }

    // ---- vertical + output
    const df = g.df;
    switch (df.kind) {
        .yuv, .gray, .nv => {
            for (0..@intCast(g.dst_h)) |yu| {
                const y: i32 = @intCast(yu);
                const d = rowPtrMut(dst[0], dst_stride[0], y);
                simd.vplane(d, dW, g.lum.ptr, g.lum_stride, &g.vl, yu);
            }
            if (df.kind == .yuv) {
                for (0..@intCast(g.chr_dst_h)) |yu| {
                    const y: i32 = @intCast(yu);
                    simd.vplane(rowPtrMut(dst[1], dst_stride[1], y), cdW, g.cu.ptr, g.chr_stride, &g.vc, yu);
                    simd.vplane(rowPtrMut(dst[2], dst_stride[2], y), cdW, g.cv.ptr, g.chr_stride, &g.vc, yu);
                }
            } else if (df.kind == .nv) {
                for (0..@intCast(g.chr_dst_h)) |yu| {
                    const y: i32 = @intCast(yu);
                    simd.vnv(rowPtrMut(dst[1], dst_stride[1], y), cdW, g.cu.ptr, g.cv.ptr, g.chr_stride, &g.vc, yu, df.swap_uv);
                }
            }
        },
        .rgb => {
            for (0..@intCast(g.dst_h)) |yu| {
                const y: i32 = @intCast(yu);
                const d = rowPtrMut(dst[0], dst_stride[0], y);
                simd.vpacked(g, d, yu);
            }
        },
    }
}

