// Inner loops of the generic pipeline.
const std = @import("std");
const generic = @import("generic.zig");
const Filter = generic.Filter;
const Generic = generic.Generic;

pub fn rgbToY(row: [*]const u8, out: [*]i16, w: usize, bpp: u3, ri: u3, gi: u3, bi: u3, ry: i32, gy: i32, by: i32) void {
    const st: usize = bpp;
    for (0..w) |i| {
        const r: i32 = row[i * st + ri];
        const gg: i32 = row[i * st + gi];
        const b: i32 = row[i * st + bi];
        out[i] = @truncate((ry * r + gy * gg + by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbaToA(row: [*]const u8, out: [*]i16, w: usize) void {
    for (0..w) |i| {
        const a: i32 = row[i * 4 + 3];
        out[i] = @intCast((a << 6) | (a >> 2));
    }
}

pub fn rgbToUV(row: [*]const u8, ou: [*]i16, ov: [*]i16, w: usize, bpp: u3, ri: u3, gi: u3, bi: u3, g: *const Generic) void {
    const st: usize = bpp;
    for (0..w) |i| {
        const r: i32 = row[i * st + ri];
        const gg: i32 = row[i * st + gi];
        const b: i32 = row[i * st + bi];
        ou[i] = @truncate((g.ru * r + g.gu * gg + g.bu * b + (256 << 14) + (1 << 8)) >> 9);
        ov[i] = @truncate((g.rv * r + g.gv * gg + g.bv * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUVHalf(row: [*]const u8, ou: [*]i16, ov: [*]i16, cw: usize, bpp: u3, ri: u3, gi: u3, bi: u3, g: *const Generic) void {
    const st: usize = bpp;
    for (0..cw) |i| {
        const p = row + 2 * i * st;
        const r: i32 = @as(i32, p[ri]) + p[st + ri];
        const gg: i32 = @as(i32, p[gi]) + p[st + gi];
        const b: i32 = @as(i32, p[bi]) + p[st + bi];
        ou[i] = @truncate((g.ru * r + g.gu * gg + g.bu * b + (256 << 15) + (1 << 9)) >> 10);
        ov[i] = @truncate((g.rv * r + g.gv * gg + g.bv * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

pub fn hscale8(out: [*]i16, dw: usize, src: [*]const u8, f: *const Filter) void {
    const fs: usize = @intCast(f.size);
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, src[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(val >> 7, 32767));
    }
}

pub fn hscale16(out: [*]i16, dw: usize, src: [*]const i16, f: *const Filter) void {
    const fs: usize = @intCast(f.size);
    const s: [*]const u16 = @ptrCast(src);
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val +%= @as(i32, s[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(val >> 13, 32767));
    }
}

inline fn lineIdx(f: *const Filter, y: usize, j: usize, nlines: usize) usize {
    _ = nlines;
    const first: i32 = @max(1 - f.size, f.pos[y]);
    return @intCast(first + @as(i32, @intCast(j)));
}

inline fn clip8(v: i32) u8 {
    return if (v < 0) 0 else if (v > 255) 255 else @intCast(v);
}

pub fn vplane(d: [*]u8, w: usize, buf: [*]const i16, stride: usize, f: *const Filter, y: usize) void {
    const fs: usize = @intCast(f.size);
    const coef = f.coef[y * fs ..];
    const first: usize = @intCast(@max(1 - f.size, f.pos[y]));
    for (0..w) |i| {
        var val: i32 = 64 << 12;
        for (0..fs) |j| val += @as(i32, buf[(first + j) * stride + i]) * coef[j];
        d[i] = clip8(val >> 19);
    }
}

pub fn vnv(d: [*]u8, w: usize, bu: [*]const i16, bv: [*]const i16, stride: usize, f: *const Filter, y: usize, swap: bool) void {
    const fs: usize = @intCast(f.size);
    const coef = f.coef[y * fs ..];
    const first: usize = @intCast(@max(1 - f.size, f.pos[y]));
    for (0..w) |i| {
        var u: i32 = 64 << 12;
        var v: i32 = 64 << 12;
        for (0..fs) |j| {
            u += @as(i32, bu[(first + j) * stride + i]) * coef[j];
            v += @as(i32, bv[(first + j) * stride + i]) * coef[j];
        }
        if (swap) {
            d[2 * i] = clip8(v >> 19);
            d[2 * i + 1] = clip8(u >> 19);
        } else {
            d[2 * i] = clip8(u >> 19);
            d[2 * i + 1] = clip8(v >> 19);
        }
    }
}

inline fn clip30(v: i32) i32 {
    if (v & ~@as(i32, (1 << 30) - 1) != 0) {
        return (~v >> 31) & ((1 << 30) - 1);
    }
    return v;
}

inline fn writeFull(g: *const Generic, d: [*]u8, Y0: i32, U: i32, V: i32, A: i32, has_alpha: bool) void {
    var Y = Y0 -% g.y_off;
    Y *%= g.y_coef;
    Y +%= 1 << 21;
    var R = Y +% V *% g.v2r;
    var G = Y +% V *% g.v2g +% U *% g.u2g;
    var B = Y +% U *% g.u2b;
    if ((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000))) != 0) {
        R = clip30(R);
        G = clip30(G);
        B = clip30(B);
    }
    const df = g.df;
    d[df.ri] = @intCast(R >> 22);
    d[df.gi] = @intCast(G >> 22);
    d[df.bi] = @intCast(B >> 22);
    if (df.bpp == 4) d[3] = if (has_alpha) @intCast(A & 0xff) else 255;
}

inline fn writeHalf(g: *const Generic, d: [*]u8, Y1: i32, Y2: i32, U: i32, V: i32) void {
    const cu: usize = @intCast(std.math.clamp(U, 0, 255));
    const cv: usize = @intCast(std.math.clamp(V, 0, 255));
    const rb = g.t_rv[cv];
    const gb = g.t_gu[cu] + g.t_gv[cv];
    const bb = g.t_bu[cu];
    const df = g.df;
    const st: usize = df.bpp;
    inline for (0..2) |k| {
        const Yk = if (k == 0) Y1 else Y2;
        const o = d + k * st;
        o[df.ri] = g.ytab[@intCast(std.math.clamp(rb + Yk, 0, 2047))];
        o[df.gi] = g.ytab[@intCast(std.math.clamp(gb + Yk, 0, 2047))];
        o[df.bi] = g.ytab[@intCast(std.math.clamp(bb + Yk, 0, 2047))];
        if (st == 4) o[3] = 255;
    }
}

pub fn vpacked(g: *Generic, d: [*]u8, y: usize) void {
    const lf: usize = @intCast(g.vl.size);
    const cf: usize = @intCast(g.vc.size);
    const cy = y >> g.chr_dst_vsub;
    const lcoef = g.vl.coef[y * lf ..];
    const ccoef = g.vc.coef[cy * cf ..];
    const firstL: usize = @intCast(@max(1 - g.vl.size, g.vl.pos[y]));
    const firstC: usize = @intCast(@max(1 - g.vc.size, g.vc.pos[cy]));
    const ls = g.lum_stride;
    const cs = g.chr_stride;
    const dW: usize = @intCast(g.dst_w);
    const st: usize = g.df.bpp;
    const ha = g.need_alpha;

    const c0u: u32 = @as(u16, @bitCast(ccoef[0]));
    const c1u: u32 = if (cf >= 2) @as(u16, @bitCast(ccoef[1])) else 0;
    const l0u: u32 = @as(u16, @bitCast(lcoef[0]));
    const l1u: u32 = if (lf >= 2) @as(u16, @bitCast(lcoef[1])) else 0;

    var mode: enum { one, two, x } = .x;
    var uvalpha: i32 = 0;
    var yalpha: i32 = 0;
    if (lf == 1 and cf == 1) {
        mode = .one;
        uvalpha = 0;
    } else if (lf == 1 and cf == 2 and c0u + c1u == 4096 and c1u <= 4096) {
        mode = .one;
        uvalpha = @intCast(c1u);
    } else if (lf == 2 and cf == 2 and l0u + l1u == 4096 and l1u <= 4096 and c0u + c1u == 4096 and c1u <= 4096) {
        mode = .two;
        yalpha = @intCast(l1u);
        uvalpha = @intCast(c1u);
    }

    const l0 = g.lum[firstL * ls ..];
    const u0 = g.cu[firstC * cs ..];
    const v0 = g.cv[firstC * cs ..];
    const a0 = if (ha) g.alp[firstL * ls ..] else g.lum[0..0];

    if (g.full_chr) {
        switch (mode) {
            .one => {
                if (uvalpha < 2048) {
                    for (0..dW) |i| {
                        const Y: i32 = @as(i32, l0[i]) * 4;
                        const U: i32 = (@as(i32, u0[i]) - (128 << 7)) * 4;
                        const V: i32 = (@as(i32, v0[i]) - (128 << 7)) * 4;
                        var A: i32 = 0;
                        if (ha) {
                            A = (@as(i32, a0[i]) + 64) >> 7;
                            if (A & 0x100 != 0) A = clip8(A);
                        }
                        writeFull(g, d + i * st, Y, U, V, A, ha);
                    }
                } else {
                    const u1 = g.cu[(firstC + 1) * cs ..];
                    const v1 = g.cv[(firstC + 1) * cs ..];
                    for (0..dW) |i| {
                        const Y: i32 = @as(i32, l0[i]) * 4;
                        const U: i32 = (@as(i32, u0[i]) + u1[i] - (128 << 8)) * 2;
                        const V: i32 = (@as(i32, v0[i]) + v1[i] - (128 << 8)) * 2;
                        var A: i32 = 0;
                        if (ha) {
                            A = (@as(i32, a0[i]) + 64) >> 7;
                            if (A & 0x100 != 0) A = clip8(A);
                        }
                        writeFull(g, d + i * st, Y, U, V, A, ha);
                    }
                }
            },
            .two => {
                const l1 = g.lum[(firstL + 1) * ls ..];
                const u1 = g.cu[(firstC + 1) * cs ..];
                const v1 = g.cv[(firstC + 1) * cs ..];
                const a1 = if (ha) g.alp[(firstL + 1) * ls ..] else g.lum[0..0];
                const ya1 = 4096 - yalpha;
                const uva1 = 4096 - uvalpha;
                for (0..dW) |i| {
                    const Y = (@as(i32, l0[i]) * ya1 + @as(i32, l1[i]) * yalpha) >> 10;
                    const U = (@as(i32, u0[i]) * uva1 + @as(i32, u1[i]) * uvalpha - (128 << 19)) >> 10;
                    const V = (@as(i32, v0[i]) * uva1 + @as(i32, v1[i]) * uvalpha - (128 << 19)) >> 10;
                    var A: i32 = 0;
                    if (ha) {
                        A = (@as(i32, a0[i]) * ya1 + @as(i32, a1[i]) * yalpha + (1 << 18)) >> 19;
                        if (A & 0x100 != 0) A = clip8(A);
                    }
                    writeFull(g, d + i * st, Y, U, V, A, ha);
                }
            },
            .x => {
                for (0..dW) |i| {
                    var Y: i32 = 1 << 9;
                    var U: i32 = (1 << 9) - (128 << 19);
                    var V: i32 = (1 << 9) - (128 << 19);
                    for (0..lf) |j| Y += @as(i32, g.lum[(firstL + j) * ls + i]) * lcoef[j];
                    for (0..cf) |j| {
                        U += @as(i32, g.cu[(firstC + j) * cs + i]) * ccoef[j];
                        V += @as(i32, g.cv[(firstC + j) * cs + i]) * ccoef[j];
                    }
                    Y >>= 10;
                    U >>= 10;
                    V >>= 10;
                    var A: i32 = 0;
                    if (ha) {
                        A = 1 << 18;
                        for (0..lf) |j| A += @as(i32, g.alp[(firstL + j) * ls + i]) * lcoef[j];
                        A >>= 19;
                        if (A & 0x100 != 0) A = clip8(A);
                    }
                    writeFull(g, d + i * st, Y, U, V, A, ha);
                }
            },
        }
    } else {
        const n = (dW + 1) >> 1;
        switch (mode) {
            .one => {
                if (uvalpha < 2048) {
                    for (0..n) |i| {
                        const Y1 = (@as(i32, l0[2 * i]) + 64) >> 7;
                        const Y2 = (@as(i32, l0[2 * i + 1]) + 64) >> 7;
                        const U = (@as(i32, u0[i]) + 64) >> 7;
                        const V = (@as(i32, v0[i]) + 64) >> 7;
                        writeHalf(g, d + 2 * i * st, Y1, Y2, U, V);
                    }
                } else {
                    const u1 = g.cu[(firstC + 1) * cs ..];
                    const v1 = g.cv[(firstC + 1) * cs ..];
                    for (0..n) |i| {
                        const Y1 = (@as(i32, l0[2 * i]) + 64) >> 7;
                        const Y2 = (@as(i32, l0[2 * i + 1]) + 64) >> 7;
                        const U = (@as(i32, u0[i]) + u1[i] + 128) >> 8;
                        const V = (@as(i32, v0[i]) + v1[i] + 128) >> 8;
                        writeHalf(g, d + 2 * i * st, Y1, Y2, U, V);
                    }
                }
            },
            .two => {
                const l1 = g.lum[(firstL + 1) * ls ..];
                const u1 = g.cu[(firstC + 1) * cs ..];
                const v1 = g.cv[(firstC + 1) * cs ..];
                const ya1 = 4096 - yalpha;
                const uva1 = 4096 - uvalpha;
                for (0..n) |i| {
                    const Y1 = (@as(i32, l0[2 * i]) * ya1 + @as(i32, l1[2 * i]) * yalpha) >> 19;
                    const Y2 = (@as(i32, l0[2 * i + 1]) * ya1 + @as(i32, l1[2 * i + 1]) * yalpha) >> 19;
                    const U = (@as(i32, u0[i]) * uva1 + @as(i32, u1[i]) * uvalpha) >> 19;
                    const V = (@as(i32, v0[i]) * uva1 + @as(i32, v1[i]) * uvalpha) >> 19;
                    writeHalf(g, d + 2 * i * st, Y1, Y2, U, V);
                }
            },
            .x => {
                for (0..n) |i| {
                    var Y1: i32 = 1 << 18;
                    var Y2: i32 = 1 << 18;
                    var U: i32 = 1 << 18;
                    var V: i32 = 1 << 18;
                    for (0..lf) |j| {
                        Y1 += @as(i32, g.lum[(firstL + j) * ls + 2 * i]) * lcoef[j];
                        Y2 += @as(i32, g.lum[(firstL + j) * ls + 2 * i + 1]) * lcoef[j];
                    }
                    for (0..cf) |j| {
                        U += @as(i32, g.cu[(firstC + j) * cs + i]) * ccoef[j];
                        V += @as(i32, g.cv[(firstC + j) * cs + i]) * ccoef[j];
                    }
                    writeHalf(g, d + 2 * i * st, Y1 >> 19, Y2 >> 19, U >> 19, V >> 19);
                }
            },
        }
    }
}

