    return .{ .r = dupOff(r), .g = dupOff(g), .b = dupOff(b) };
}

inline fn chan(c: *const YC, y: I16, off: I16) U8x16 {
    const z = y + off;
    const cyl: I16 = @splat(c.cyl);
    const pl: U16 = @bitCast(z *% cyl);
    const ph: I16 = @truncate((@as(I32x16, z) * @as(I32x16, cyl)) >> @splat(16));
    const carry: U16 = (pl +| @as(U16, @splat(c.blm1))) -| @as(U16, @splat(65534));
    const v = z + ph + @as(I16, @splat(c.bh)) + @as(I16, @bitCast(carry));
    return @intCast(@max(@min(v, @as(I16, @splat(255))), @as(I16, @splat(0))));
}

inline fn zip8(a: U8x16, b: U8x16) @Vector(32, u8) {
    const m = comptime blk: {
        var mm: [32]i32 = undefined;
        for (0..16) |k| {
            mm[2 * k] = @intCast(k);
            mm[2 * k + 1] = ~@as(i32, @intCast(k));
        }
        break :blk mm;
    };
    return @shuffle(u8, a, b, m);
}
inline fn zip16(a: U16, b: U16) @Vector(32, u16) {
    const m = comptime blk: {
        var mm: [32]i32 = undefined;
        for (0..16) |k| {
            mm[2 * k] = @intCast(k);
            mm[2 * k + 1] = ~@as(i32, @intCast(k));
        }
        break :blk mm;
    };
    return @shuffle(u16, a, b, m);
}

const mask_rgb48 = blk: {
    var m: [48]i32 = undefined;
    for (0..16) |p| {
        m[3 * p] = @intCast(2 * p);
        m[3 * p + 1] = @intCast(2 * p + 1);
        m[3 * p + 2] = ~@as(i32, @intCast(p));
    }
    break :blk m;
};

inline fn putPixels(comptime db: usize, comptime dr: usize, c: *const YC, py: [*]const u8, o: Offs, d: [*]u8) void {
    const yb: U8x16 = py[0..16].*;
    const y16: I16 = @intCast(yb);
    const r = chan(c, y16, o.r);
    const g = chan(c, y16, o.g);
    const b = chan(c, y16, o.b);
    const c0 = if (dr == 0) r else b;
    const c2 = if (dr == 0) b else r;
    if (db == 4) {
