        const lo2: U16 = @bitCast(zip8(c0, g));
        const hi2: U16 = @bitCast(zip8(c2, ff));
        d[0..64].* = @bitCast(zip16(lo2, hi2));
    } else {
        d[0..48].* = @shuffle(u8, zip8(c0, g), c2, mask_rgb48);
    }
}

fn yuv2rgbT(comptime db: usize, comptime dr: usize, is422: bool, t: *const RgbTables, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int, w: usize, h: usize) void {
