            const pu = rowc(src[1].?, ss[1], y);
            const pv = rowc(src[2].?, ss[2], y);
            const d = rowm(dst[0].?, ds[0], y);
            var x: usize = 0;
            while (x < wv) : (x += 16) {
                const o = chromaOffs(c, pu + (x >> 1), pv + (x >> 1));
                putPixels(db, dr, c, py + x, o, d + x * db);
            }
