// ---------------------------------------------------------------- vector paths
pub const V16i = @Vector(16, i32);
const V16s = @Vector(16, i16);
const V16b = @Vector(16, u8);

inline fn spl(v: i32) V16i {
    return @splat(v);
}

inline fn ld16(p: [*]const i16) V16i {
    const v: V16s = p[0..16].*;
    return @intCast(v);
}

inline fn clampU8v(v: V16i) V16b {
    return @intCast(@max(@min(v, spl(255)), spl(0)));
}

fn chanIdx(comptime n: usize, comptime bpp: usize, comptime c: usize, comptime step: usize, comptime off: usize) [n]i32 {
    var r: [n]i32 = undefined;
    for (0..n) |k| r[k] = @intCast((k * step + off) * bpp + c);
    return r;
}

inline fn loadChan16(comptime bpp: usize, comptime c: usize, p: [*]const u8) V16i {
    const v: @Vector(16 * bpp, u8) = p[0 .. 16 * bpp].*;
    const s: V16b = @shuffle(u8, v, undefined, comptime chanIdx(16, bpp, c, 1, 0));
    return @intCast(s);
}

inline fn loadPairSum16(comptime bpp: usize, comptime c: usize, p: [*]const u8) V16i {
    const v: @Vector(32 * bpp, u8) = p[0 .. 32 * bpp].*;
    const a: V16b = @shuffle(u8, v, undefined, comptime chanIdx(16, bpp, c, 2, 0));
    const b: V16b = @shuffle(u8, v, undefined, comptime chanIdx(16, bpp, c, 2, 1));
    return @as(V16i, @intCast(a)) + @as(V16i, @intCast(b));
}

inline fn store16(p: [*]i16, v: V16i) void {
    const s: V16s = @truncate(v);
    p[0..16].* = s;
}

pub fn isIdentity(f: *const Filter, n: usize) bool {
    if (f.size != 1) return false;
    for (0..n) |i| {
        if (f.pos[i] != @as(i32, @intCast(i)) or f.coef[i] != 16384) return false;
    }
    return true;
}

// rgb -> Y (and alpha) with identity horizontal filter: out = min(2*Y14, 32767)
pub fn rgbToYIdent(row: [*]const u8, out: [*]i16, w: usize, sf: generic.Fmt, g: *const Generic) void {
    switch (sf.bpp) {
        3 => if (sf.ri == 0) rgbToYIdentT(3, 0, 2, row, out, w, g) else rgbToYIdentT(3, 2, 0, row, out, w, g),
        else => if (sf.ri == 0) rgbToYIdentT(4, 0, 2, row, out, w, g) else rgbToYIdentT(4, 2, 0, row, out, w, g),
    }
}

fn rgbToYIdentT(comptime bpp: usize, comptime ri: usize, comptime bi: usize, row: [*]const u8, out: [*]i16, w: usize, g: *const Generic) void {
    var i: usize = 0;
    const ry = spl(g.ry);
    const gy = spl(g.gy);
    const by = spl(g.by);
    while (i + 16 <= w) : (i += 16) {
        const p = row + i * bpp;
        const r = loadChan16(bpp, ri, p);
        const gg = loadChan16(bpp, 1, p);
        const b = loadChan16(bpp, bi, p);
        const y = (ry * r + gy * gg + by * b + spl((32 << 14) + (1 << 8))) >> @splat(9);
        store16(out + i, @min(y + y, spl(32767)));
    }
    while (i < w) : (i += 1) {
        const r: i32 = row[i * bpp + ri];
        const gg: i32 = row[i * bpp + 1];
        const b: i32 = row[i * bpp + bi];
        const y = (g.ry * r + g.gy * gg + g.by * b + (32 << 14) + (1 << 8)) >> 9;
        out[i] = @intCast(@min(y * 2, 32767));
    }
}

pub fn alphaIdent(row: [*]const u8, out: [*]i16, w: usize) void {
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const a = loadChan16(4, 3, row + i * 4);
        store16(out + i, ((a << @splat(6)) | (a >> @splat(2))) * spl(2));
    }
    while (i < w) : (i += 1) {
        const a: i32 = row[i * 4 + 3];
        out[i] = @intCast(((a << 6) | (a >> 2)) * 2);
    }
}

pub fn rgbToUVIdent(row: [*]const u8, ou: [*]i16, ov: [*]i16, cw: usize, half: bool, sf: generic.Fmt, g: *const Generic) void {
    if (half) {
        switch (sf.bpp) {
            3 => if (sf.ri == 0) rgbToUVIdentT(3, 0, 2, true, row, ou, ov, cw, g) else rgbToUVIdentT(3, 2, 0, true, row, ou, ov, cw, g),
            else => if (sf.ri == 0) rgbToUVIdentT(4, 0, 2, true, row, ou, ov, cw, g) else rgbToUVIdentT(4, 2, 0, true, row, ou, ov, cw, g),
        }
    } else {
        switch (sf.bpp) {
            3 => if (sf.ri == 0) rgbToUVIdentT(3, 0, 2, false, row, ou, ov, cw, g) else rgbToUVIdentT(3, 2, 0, false, row, ou, ov, cw, g),
            else => if (sf.ri == 0) rgbToUVIdentT(4, 0, 2, false, row, ou, ov, cw, g) else rgbToUVIdentT(4, 2, 0, false, row, ou, ov, cw, g),
        }
    }
}

fn rgbToUVIdentT(comptime bpp: usize, comptime ri: usize, comptime bi: usize, comptime half: bool, row: [*]const u8, ou: [*]i16, ov: [*]i16, cw: usize, g: *const Generic) void {
    var i: usize = 0;
    const ru = spl(g.ru);
    const gu = spl(g.gu);
    const bu = spl(g.bu);
    const rv = spl(g.rv);
    const gv = spl(g.gv);
    const bv = spl(g.bv);
    while (i + 16 <= cw) : (i += 16) {
        var r: V16i = undefined;
        var gg: V16i = undefined;
        var b: V16i = undefined;
        var u: V16i = undefined;
        var v: V16i = undefined;
        if (half) {
            const p = row + 2 * i * bpp;
            r = loadPairSum16(bpp, ri, p);
            gg = loadPairSum16(bpp, 1, p);
            b = loadPairSum16(bpp, bi, p);
            u = (ru * r + gu * gg + bu * b + spl((256 << 15) + (1 << 9))) >> @splat(10);
            v = (rv * r + gv * gg + bv * b + spl((256 << 15) + (1 << 9))) >> @splat(10);
        } else {
            const p = row + i * bpp;
            r = loadChan16(bpp, ri, p);
            gg = loadChan16(bpp, 1, p);
            b = loadChan16(bpp, bi, p);
            u = (ru * r + gu * gg + bu * b + spl((256 << 14) + (1 << 8))) >> @splat(9);
            v = (rv * r + gv * gg + bv * b + spl((256 << 14) + (1 << 8))) >> @splat(9);
        }
        store16(ou + i, @min(u + u, spl(32767)));
        store16(ov + i, @min(v + v, spl(32767)));
    }
    while (i < cw) : (i += 1) {
        var u: i32 = 0;
        var v: i32 = 0;
        if (half) {
            const p = row + 2 * i * bpp;
            const r: i32 = @as(i32, p[ri]) + p[bpp + ri];
            const gg: i32 = @as(i32, p[1]) + p[bpp + 1];
            const b: i32 = @as(i32, p[bi]) + p[bpp + bi];
            u = (g.ru * r + g.gu * gg + g.bu * b + (256 << 15) + (1 << 9)) >> 10;
            v = (g.rv * r + g.gv * gg + g.bv * b + (256 << 15) + (1 << 9)) >> 10;
        } else {
            const p = row + i * bpp;
            const r: i32 = p[ri];
            const gg: i32 = p[1];
            const b: i32 = p[bi];
            u = (g.ru * r + g.gu * gg + g.bu * b + (256 << 14) + (1 << 8)) >> 9;
            v = (g.rv * r + g.gv * gg + g.bv * b + (256 << 14) + (1 << 8)) >> 9;
        }
        ou[i] = @intCast(@min(u * 2, 32767));
        ov[i] = @intCast(@min(v * 2, 32767));
    }
}

pub fn ident8(out: [*]i16, src: [*]const u8, w: usize) void {
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const s: V16b = src[i..][0..16].*;
        store16(out + i, @as(V16i, @intCast(s)) << @splat(7));
    }
    while (i < w) : (i += 1) out[i] = @as(i16, src[i]) << 7;
}

pub fn vplaneV(d: [*]u8, w: usize, buf: [*]const i16, stride: usize, f: *const Filter, y: usize) void {
    const fs: usize = @intCast(f.size);
    const coef = f.coef[y * fs ..];
    const first: usize = @intCast(@max(1 - f.size, f.pos[y]));
    var i: usize = 0;
    const base = buf + first * stride;
    if (fs == 1 and coef[0] == 4096) {
        while (i + 16 <= w) : (i += 16) {
            d[i..][0..16].* = clampU8v((ld16(base + i) + spl(64)) >> @splat(7));
        }
    } else if (fs == 2) {
        const c0 = spl(coef[0]);
        const c1 = spl(coef[1]);
        while (i + 16 <= w) : (i += 16) {
            const acc = spl(64 << 12) +% ld16(base + i) *% c0 +% ld16(base + stride + i) *% c1;
            d[i..][0..16].* = clampU8v(acc >> @splat(19));
        }
    } else {
        while (i + 16 <= w) : (i += 16) {
            var acc = spl(64 << 12);
            for (0..fs) |j| acc +%= ld16(base + j * stride + i) *% spl(coef[j]);
            d[i..][0..16].* = clampU8v(acc >> @splat(19));
        }
    }
    while (i < w) : (i += 1) {
        var val: i32 = 64 << 12;
        for (0..fs) |j| val +%= @as(i32, buf[(first + j) * stride + i]) * coef[j];
        d[i] = clip8(val >> 19);
    }
}

fn zipIdx(comptime n: usize) [2 * n]i32 {
    var r: [2 * n]i32 = undefined;
    for (0..n) |k| {
        r[2 * k] = @intCast(k);
        r[2 * k + 1] = ~@as(i32, @intCast(k));
    }
    return r;
}

pub fn vnvV(d: [*]u8, w: usize, bu: [*]const i16, bv: [*]const i16, stride: usize, f: *const Filter, y: usize, swap: bool) void {
    const fs: usize = @intCast(f.size);
    const coef = f.coef[y * fs ..];
    const first: usize = @intCast(@max(1 - f.size, f.pos[y]));
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        var au = spl(64 << 12);
        var av = spl(64 << 12);
        for (0..fs) |j| {
            const c = spl(coef[j]);
            au +%= ld16(bu + (first + j) * stride + i) *% c;
            av +%= ld16(bv + (first + j) * stride + i) *% c;
        }
        var u8v = clampU8v(au >> @splat(19));
        var v8v = clampU8v(av >> @splat(19));
        if (swap) {
            const t = u8v;
            u8v = v8v;
            v8v = t;
        }
        const z: @Vector(32, u8) = @shuffle(u8, u8v, v8v, comptime zipIdx(16));
        d[2 * i ..][0..32].* = z;
    }
    if (i < w) vnv(d + 2 * i, w - i, bu + i, bv + i, stride, f, y, swap);
}
