// ------------------------------------------------ periodic horizontal scaler
// When dstW/srcW = P/Q with small P, Q the interior filter rows repeat every P outputs while
// the source advances by Q; those rows are evaluated 16 periods at a time.
pub const HPlan = struct {
    P: u32 = 0,
    Q: u32 = 0,
    fs: usize = 0,
    m_lo: usize = 0,
    m_hi: usize = 0,
    base: [4]i32 = .{ 0, 0, 0, 0 },
    coef: [4][16]i32 = undefined,
};

fn gcd(a: u32, b: u32) u32 {
    var x = a;
    var y = b;
    while (y != 0) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

const supported = [_][2]u32{ .{ 1, 2 }, .{ 1, 3 }, .{ 2, 1 }, .{ 3, 2 }, .{ 2, 3 }, .{ 1, 4 }, .{ 4, 1 }, .{ 3, 1 }, .{ 4, 3 }, .{ 3, 4 } };

pub fn makePlan(f: *const Filter, srcW: i32, dstW: i32) HPlan {
    var pl = HPlan{};
    const fs: usize = @intCast(f.size);
    if (fs > 16) return pl;
    const g = gcd(@intCast(dstW), @intCast(srcW));
    const P: u32 = @as(u32, @intCast(dstW)) / g;
    const Q: u32 = @as(u32, @intCast(srcW)) / g;
    var ok = false;
    for (supported) |s| {
        if (s[0] == P and s[1] == Q) ok = true;
    }
    if (!ok) return pl;
    const dW: usize = @intCast(dstW);
    const nm = dW / P;
    if (nm < 64) return pl;
    const m0 = nm / 2;
    for (0..P) |p| {
        const i = m0 * P + p;
        pl.base[p] = f.pos[i] - @as(i32, @intCast(Q * m0));
        for (0..16) |j| pl.coef[p][j] = if (j < fs) f.coef[i * fs + j] else 0;
    }
    const valid = struct {
        fn v(pl_: *const HPlan, f_: *const Filter, fs_: usize, P_: u32, Q_: u32, m: usize, srcW_: i32) bool {
            for (0..P_) |p| {
                const i = m * P_ + p;
                if (f_.pos[i] != pl_.base[p] + @as(i32, @intCast(Q_ * m))) return false;
                for (0..fs_) |j| if (f_.coef[i * fs_ + j] != pl_.coef[p][j]) return false;
                // strided 16-period loads must stay inside the source row
                if (pl_.base[p] + @as(i32, @intCast(fs_)) + @as(i32, @intCast(Q_ * (m + 16))) > srcW_) return false;
            }
            return true;
        }
    }.v;
    var lo = m0;
    while (lo > 0 and valid(&pl, f, fs, P, Q, lo - 1, srcW)) lo -= 1;
    var hi = m0;
    while (hi < nm and valid(&pl, f, fs, P, Q, hi, srcW)) hi += 1;
    if (!valid(&pl, f, fs, P, Q, m0, srcW)) return pl;
    pl.P = P;
    pl.Q = Q;
    pl.fs = fs;
    pl.m_lo = lo;
    pl.m_hi = hi;
    return pl;
}

fn strideIdx(comptime Q: usize, comptime off: usize) [16]i32 {
    var r: [16]i32 = undefined;
    for (0..16) |k| r[k] = @intCast(k * Q + off);
    return r;
}

inline fn sload(comptime T: type, comptime Q: usize, p: [*]const T) V16i {
    if (Q == 1) {
        const v: @Vector(16, T) = p[0..16].*;
        return @intCast(v);
    }
    const v: @Vector(16 * Q, T) = p[0 .. 16 * Q].*;
    const s: @Vector(16, T) = @shuffle(T, v, undefined, strideIdx(Q, 0));
    return @intCast(s);
}

fn catIdx(comptime n: usize) [2 * n]i32 {
    var r: [2 * n]i32 = undefined;
    for (0..n) |k| {
        r[k] = @intCast(k);
        r[n + k] = ~@as(i32, @intCast(k));
    }
    return r;
}

fn ilv3Idx() [48]i32 {
    var r: [48]i32 = undefined;
    for (0..16) |m| {
        r[m * 3 + 0] = @intCast(m);
        r[m * 3 + 1] = @intCast(16 + m);
        r[m * 3 + 2] = ~@as(i32, @intCast(m));
    }
    return r;
}

fn ilv4Idx() [64]i32 {
    var r: [64]i32 = undefined;
    for (0..16) |m| {
        r[m * 4 + 0] = @intCast(m);
        r[m * 4 + 1] = @intCast(16 + m);
        r[m * 4 + 2] = ~@as(i32, @intCast(m));
        r[m * 4 + 3] = ~@as(i32, @intCast(16 + m));
    }
    return r;
}

fn hscalePerT(comptime T: type, comptime P: usize, comptime Q: usize, pl: *const HPlan, out: [*]i16, src: [*]const T) void {
    const sh: u5 = if (T == u8) 7 else 13;
    const fs = pl.fs;
    var m = pl.m_lo;
    while (m + 16 <= pl.m_hi) : (m += 16) {
        var acc: [P]V16i = undefined;
        inline for (0..P) |p| {
            var a = spl(0);
            const sp = src + @as(usize, @intCast(pl.base[p] + @as(i32, @intCast(Q * m))));
            for (0..fs) |j| a +%= sload(T, Q, sp + j) *% spl(pl.coef[p][j]);
            acc[p] = @min(a >> @splat(sh), spl(32767));
        }
        const o = out + m * P;
        if (P == 1) {
            store16(o, acc[0]);
        } else if (P == 2) {
            const s: @Vector(32, i16) = @shuffle(i16, @as(V16s, @truncate(acc[0])), @as(V16s, @truncate(acc[1])), zipIdx(16));
            o[0..32].* = s;
        } else if (P == 3) {
            const ab: @Vector(32, i16) = @shuffle(i16, @as(V16s, @truncate(acc[0])), @as(V16s, @truncate(acc[1])), catIdx(16));
            const s: @Vector(48, i16) = @shuffle(i16, ab, @as(V16s, @truncate(acc[2])), ilv3Idx());
            o[0..48].* = s;
        } else {
            const ab: @Vector(32, i16) = @shuffle(i16, @as(V16s, @truncate(acc[0])), @as(V16s, @truncate(acc[1])), catIdx(16));
            const cd: @Vector(32, i16) = @shuffle(i16, @as(V16s, @truncate(acc[2])), @as(V16s, @truncate(acc[3])), catIdx(16));
            const s: @Vector(64, i16) = @shuffle(i16, ab, cd, ilv4Idx());
            o[0..64].* = s;
        }
    }
}

fn hscaleScalarRange(comptime T: type, out: [*]i16, src: [*]const T, f: *const Filter, a: usize, b: usize) void {
    const fs: usize = @intCast(f.size);
    const sh: u5 = if (T == u8) 7 else 13;
    var i = a;
    while (i < b) : (i += 1) {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val +%= @as(i32, src[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(val >> sh, 32767));
    }
}

pub fn hscaleAny(comptime T: type, out: [*]i16, dw: usize, src: [*]const T, f: *const Filter, pl: *const HPlan) void {
    if (pl.P == 0) return hscaleScalarRange(T, out, src, f, 0, dw);
    const P: usize = pl.P;
    const nvec = (pl.m_hi - pl.m_lo) / 16 * 16;
    const v0 = pl.m_lo * P;
    const v1 = (pl.m_lo + nvec) * P;
    hscaleScalarRange(T, out, src, f, 0, v0);
    inline for (supported) |s| {
        if (pl.P == s[0] and pl.Q == s[1]) hscalePerT(T, s[0], s[1], pl, out, src);
    }
    hscaleScalarRange(T, out, src, f, v1, dw);
}

pub fn rgbToYV(row: [*]const u8, out: [*]i16, w: usize, sf: generic.Fmt, g: *const Generic) void {
    switch (sf.bpp) {
        3 => if (sf.ri == 0) rgbToYT(3, 0, 2, row, out, w, g) else rgbToYT(3, 2, 0, row, out, w, g),
        else => if (sf.ri == 0) rgbToYT(4, 0, 2, row, out, w, g) else rgbToYT(4, 2, 0, row, out, w, g),
    }
}

fn rgbToYT(comptime bpp: usize, comptime ri: usize, comptime bi: usize, row: [*]const u8, out: [*]i16, w: usize, g: *const Generic) void {
    var i: usize = 0;
    const ry = spl(g.ry);
    const gy = spl(g.gy);
    const by = spl(g.by);
    while (i + 16 <= w) : (i += 16) {
        const p = row + i * bpp;
        const y = (ry * loadChan16(bpp, ri, p) + gy * loadChan16(bpp, 1, p) + by * loadChan16(bpp, bi, p) + spl((32 << 14) + (1 << 8))) >> @splat(9);
        store16(out + i, y);
    }
