// ------------------------------------------------ vectorised packed RGB output
inline fn clip30v(v: V16i) V16i {
    const m = spl((1 << 30) - 1);
    const bad = (v & ~m) != spl(0);
    return @select(i32, bad, (~v >> @splat(31)) & m, v);
}

fn rgbIlv(comptime bpp: usize, comptime ri: usize, comptime bi: usize) [16 * bpp]i32 {
    // sources: concat(r,g) = 0..31, concat(b,a) = ~0..~31
    var r: [16 * bpp]i32 = undefined;
    for (0..16) |k| {
        r[k * bpp + ri] = @intCast(k);
        r[k * bpp + 1] = @intCast(16 + k);
        r[k * bpp + bi] = ~@as(i32, @intCast(k));
        if (bpp == 4) r[k * bpp + 3] = ~@as(i32, @intCast(16 + k));
    }
    return r;
}

inline fn storeRGB(comptime bpp: usize, comptime ri: usize, comptime bi: usize, d: [*]u8, r: V16b, gg: V16b, b: V16b, a: V16b) void {
    const rg: @Vector(32, u8) = @shuffle(u8, r, gg, catIdx(16));
    const ba: @Vector(32, u8) = @shuffle(u8, b, a, catIdx(16));
    const o: @Vector(16 * bpp, u8) = @shuffle(u8, rg, ba, rgbIlv(bpp, ri, bi));
    d[0 .. 16 * bpp].* = o;
}

inline fn writeFullV(comptime bpp: usize, comptime ri: usize, comptime bi: usize, g: *const Generic, d: [*]u8, Y0: V16i, U: V16i, V: V16i, A: V16b) void {
    const Y = (Y0 -% spl(g.y_off)) *% spl(g.y_coef) +% spl(1 << 21);
    const R = clip30v(Y +% V *% spl(g.v2r));
    const G = clip30v(Y +% V *% spl(g.v2g) +% U *% spl(g.u2g));
    const B = clip30v(Y +% U *% spl(g.u2b));
    storeRGB(bpp, ri, bi, d, @intCast(R >> @splat(22)), @intCast(G >> @splat(22)), @intCast(B >> @splat(22)), A);
}

fn dupIdx() [16]i32 {
    var r: [16]i32 = undefined;
    for (0..16) |k| r[k] = @intCast(k / 2);
    return r;
}

inline fn tabLookupV(g: *const Generic, base: V16i, Y: V16i) V16b {
    const idx = @max(@min(base + Y, spl(2047)), spl(0));
    const v = (spl(g.k_yb0) + idx * spl(g.k_cy) + spl(0x8000)) >> @splat(16);
    return clampU8v(v);
}

inline fn writeHalfV(comptime bpp: usize, comptime ri: usize, comptime bi: usize, g: *const Generic, d: [*]u8, Y: V16i, U8: V16i, V8: V16i) void {
    // U8/V8 hold 8 chroma values in lanes 0..7
    const cu = @max(@min(@shuffle(i32, U8, undefined, dupIdx()), spl(255)), spl(0));
    const cv = @max(@min(@shuffle(i32, V8, undefined, dupIdx()), spl(255)), spl(0));
    const yo = spl(g.k_yoffs);
    const rb = yo - spl(g.k_crv >> 9) + ((cv * spl(g.k_crv)) >> @splat(16));
    const gb = yo - spl(g.k_cgu >> 9) + ((cu * spl(g.k_cgu)) >> @splat(16)) - spl(g.k_cgv >> 9) + ((cv * spl(g.k_cgv)) >> @splat(16));
    const bb = yo - spl(g.k_cbu >> 9) + ((cu * spl(g.k_cbu)) >> @splat(16));
    storeRGB(bpp, ri, bi, d, tabLookupV(g, rb, Y), tabLookupV(g, gb, Y), tabLookupV(g, bb, Y), @splat(255));
}

inline fn ld8w(p: [*]const i16) V16i {
    // 8 values in lanes 0..7 (lanes 8..15 duplicate, unused)
    const v: @Vector(8, i16) = p[0..8].*;
    const w: @Vector(16, i16) = @shuffle(i16, v, undefined, [16]i32{ 0, 1, 2, 3, 4, 5, 6, 7, 0, 1, 2, 3, 4, 5, 6, 7 });
    return @intCast(w);
}

pub fn vpackedV(g: *Generic, d: [*]u8, y: usize) void {
    const df = g.df;
    const done = switch (df.bpp) {
        3 => if (df.ri == 0) vpackedT(3, 0, 2, g, d, y) else vpackedT(3, 2, 0, g, d, y),
        else => if (df.ri == 0) vpackedT(4, 0, 2, g, d, y) else vpackedT(4, 2, 0, g, d, y),
    };
    vpacked(g, d, y, done);
}

fn vpackedT(comptime bpp: usize, comptime ri: usize, comptime bi: usize, g: *Generic, d: [*]u8, y: usize) usize {
