const std = @import("std");
const U = @import("unscaled.zig");
fn planes(fmt: c_int, w: usize, h: usize) struct { n: usize, pw: [3]usize, ph: [3]usize } {
    return switch (fmt) {
        0 => .{ .n = 3, .pw = .{ w, w / 2, w / 2 }, .ph = .{ h, h / 2, h / 2 } },
        1 => .{ .n = 3, .pw = .{ w, w / 2, w / 2 }, .ph = .{ h, h, h } },
        3, 4 => .{ .n = 2, .pw = .{ w, w, 0 }, .ph = .{ h, h / 2, 0 } },
        5, 6 => .{ .n = 1, .pw = .{ 3 * w, 0, 0 }, .ph = .{ h, 0, 0 } },
        7, 8 => .{ .n = 1, .pw = .{ 4 * w, 0, 0 }, .ph = .{ h, 0, 0 } },
        9 => .{ .n = 1, .pw = .{ w, 0, 0 }, .ph = .{ h, 0, 0 } },
        else => unreachable,
    };
}
fn run(sf: c_int, df: c_int, w: usize, h: usize, pad: usize, sbuf: *[3][]u8, out: *[3][]u8, rnd: std.Random) !void {
    const a = std.heap.page_allocator;
    const sp = planes(sf, w, h);
    const dp = planes(df, w, h);
    var src: [4]?[*]const u8 = .{ null, null, null, null };
    var ss: [4]c_int = .{ 0, 0, 0, 0 };
    var dst: [4]?[*]u8 = .{ null, null, null, null };
    var ds: [4]c_int = .{ 0, 0, 0, 0 };
    for (0..sp.n) |p| {
        const st = sp.pw[p] + pad;
        const b = try a.alloc(u8, st * sp.ph[p] + 64);
        if (pad == 0) { rnd.bytes(b); sbuf[p] = try a.dupe(u8, b); } else {
            for (0..sp.ph[p]) |y| @memcpy(b[y * st ..][0..sp.pw[p]], sbuf[p][y * sp.pw[p] ..][0..sp.pw[p]]);
        }
        src[p] = b.ptr;
        ss[p] = @intCast(st);
    }
    for (0..dp.n) |p| {
        const st = dp.pw[p] + pad;
        const b = try a.alloc(u8, st * dp.ph[p] + 64);
        dst[p] = b.ptr;
        ds[p] = @intCast(st);
    }
    var u: U.Unscaled = .{};
    if (!U.init(&u, @intCast(w), @intCast(h), sf, @intCast(w), @intCast(h), df, 1)) return error.NoInit;
    U.process(&u, &src, &ss, &dst, &ds);
    for (0..dp.n) |p| {
        const st = dp.pw[p] + pad;
        if (pad == 0) { out[p] = (dst[p].?)[0 .. st * dp.ph[p]]; } else {
            for (0..dp.ph[p]) |y| {
                if (!std.mem.eql(u8, out[p][y * dp.pw[p] ..][0..dp.pw[p]], (dst[p].?)[y * st ..][0..dp.pw[p]])) {
                    std.debug.print("mismatch {}->{} w{} plane {} row {}\n", .{ sf, df, w, p, y });
                    return error.Mismatch;
                }
            }
        }
    }
}
