// ------------------------------------------------ windowed horizontal scaler (fs <= 8)
pub fn padCoefs(f: *const Filter, dw: usize) ?[]i32 {
    const fs: usize = @intCast(f.size);
    if (fs > 8) return null;
    const c = std.heap.c_allocator.alloc(i32, dw * 8) catch return null;
    for (0..dw) |i| {
        for (0..8) |j| c[i * 8 + j] = if (j < fs) f.coef[i * fs + j] else 0;
    }
    return c;
}

pub fn hscaleWin(comptime T: type, out: [*]i16, dw: usize, src: [*]const T, srcW: usize, f: *const Filter, cpad: []const i32, a: usize, b: usize) void {
    const sh: u5 = if (T == u8) 7 else 13;
    var i = a;
    while (i < b) : (i += 1) {
        const p: usize = @intCast(f.pos[i]);
        if (p + 8 > srcW) break;
        const s: @Vector(8, T) = src[p..][0..8].*;
        const c: @Vector(8, i32) = cpad[i * 8 ..][0..8].*;
        const v = @reduce(.Add, @as(@Vector(8, i32), @intCast(s)) *% c);
        out[i] = @intCast(@min(v >> sh, 32767));
    }
    hscaleScalarRange(T, out, src, f, i, b);
    _ = dw;
}
