// ------------------------------------------------ pmaddwd-style RGB input conversion
const V32s = @Vector(32, i16);
const V32b = @Vector(32, u8);

// 32-byte gather from a (32*bpp*step)-byte block: lane 2k = channel ca of pixel (k*step+off),
// lane 2k+1 = channel cb (or 0 when cb == 255).
fn pairIdx(comptime bpp: usize, comptime ca: usize, comptime cb: usize, comptime step: usize, comptime off: usize) [32]i32 {
    var r: [32]i32 = undefined;
    for (0..16) |k| {
        r[2 * k] = @intCast((k * step + off) * bpp + ca);
        r[2 * k + 1] = if (cb == 255) -1 else @intCast((k * step + off) * bpp + cb);
    }
    return r;
}

inline fn maddv(a: V32s, c: V32s) V16i {
    const p = @as(@Vector(32, i32), a) * @as(@Vector(32, i32), c);
    return @shuffle(i32, p, undefined, evenIdx(16, 0)) + @shuffle(i32, p, undefined, evenIdx(16, 1));
}

fn pairConst(a: i32, b: i32) V32s {
    var r: [32]i16 = undefined;
    for (0..16) |k| {
        r[2 * k] = @intCast(a);
        r[2 * k + 1] = @intCast(b);
    }
    return r;
}

inline fn gatherPairs(comptime bpp: usize, comptime n: usize, comptime ca: usize, comptime cb: usize, comptime step: usize, comptime off: usize, p: [*]const u8) V32s {
    const v: @Vector(n, u8) = p[0..n].*;
    const z: V32b = @splat(0);
    const s: V32b = @shuffle(u8, v, z, pairIdx(bpp, ca, cb, step, off));
    return @intCast(s);
}

pub fn rgbYFast(comptime bpp: usize, comptime ri: usize, comptime bi: usize, comptime ident: bool, row: [*]const u8, out: [*]i16, w: usize, g: *const Generic) usize {
    const crg = pairConst(g.ry, g.gy);
    const cb = pairConst(g.by, 16392); // 32 * 16392 = (32 << 14) + (1 << 8)
    var bk: [32]i16 = undefined;
    for (0..16) |k| {
        bk[2 * k] = 0;
        bk[2 * k + 1] = 32;
    }
    const kv: V32s = bk;
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const p = row + i * bpp;
        const rg = gatherPairs(bpp, 16 * bpp, ri, 1, 1, 0, p);
        const b = gatherPairs(bpp, 16 * bpp, bi, 255, 1, 0, p) | kv;
        var y = (maddv(rg, crg) + maddv(b, cb)) >> @splat(9);
        if (ident) y = @min(y + y, spl(32767));
        store16(out + i, y);
    }
    return i;
}

pub fn rgbUVFast(comptime bpp: usize, comptime ri: usize, comptime bi: usize, comptime half: bool, comptime ident: bool, row: [*]const u8, ou: [*]i16, ov: [*]i16, cw: usize, g: *const Generic) usize {
    const kk: i32 = if (half) 512 else 256;
    var bk: [32]i16 = undefined;
    for (0..16) |k| {
        bk[2 * k] = 0;
        bk[2 * k + 1] = @intCast(kk);
    }
    const kv: V32s = bk;
    const cu_rg = pairConst(g.ru, g.gu);
    const cu_b = pairConst(g.bu, 16385);
    const cv_rg = pairConst(g.rv, g.gv);
    const cv_b = pairConst(g.bv, 16385);
    const sh: u5 = if (half) 10 else 9;
    var i: usize = 0;
    while (i + 16 <= cw) : (i += 16) {
        var rg: V32s = undefined;
        var b: V32s = undefined;
        if (half) {
            const p = row + 2 * i * bpp;
            rg = gatherPairs(bpp, 32 * bpp, ri, 1, 2, 0, p) + gatherPairs(bpp, 32 * bpp, ri, 1, 2, 1, p);
            b = (gatherPairs(bpp, 32 * bpp, bi, 255, 2, 0, p) + gatherPairs(bpp, 32 * bpp, bi, 255, 2, 1, p)) | kv;
        } else {
            const p = row + i * bpp;
            rg = gatherPairs(bpp, 16 * bpp, ri, 1, 1, 0, p);
            b = gatherPairs(bpp, 16 * bpp, bi, 255, 1, 0, p) | kv;
        }
        var u = (maddv(rg, cu_rg) + maddv(b, cu_b)) >> @splat(sh);
        var v = (maddv(rg, cv_rg) + maddv(b, cv_b)) >> @splat(sh);
        if (ident) {
            u = @min(u + u, spl(32767));
            v = @min(v + v, spl(32767));
        }
        store16(ou + i, u);
        store16(ov + i, v);
    }
    return i;
}
