// same-size rgb -> 8-bit luma plane (identity horizontal and vertical filters)
pub fn rgbYToPlane(row: [*]const u8, d: [*]u8, w: usize, sf: generic.Fmt, g: *const Generic) void {
    switch (sf.bpp) {
        3 => if (sf.ri == 0) rgbYToPlaneT(3, 0, 2, row, d, w, g) else rgbYToPlaneT(3, 2, 0, row, d, w, g),
        else => if (sf.ri == 0) rgbYToPlaneT(4, 0, 2, row, d, w, g) else rgbYToPlaneT(4, 2, 0, row, d, w, g),
    }
}

fn rgbYToPlaneT(comptime bpp: usize, comptime ri: usize, comptime bi: usize, row: [*]const u8, d: [*]u8, w: usize, g: *const Generic) void {
    const crg = pairConst(g.ry, g.gy);
    const cb = pairConst(g.by, 16392);
    var bk: [32]i16 = undefined;
    for (0..16) |k| {
        bk[2 * k] = 0;
        bk[2 * k + 1] = 32;
    }
    const kv: V32s = bk;
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const p = row + i * bpp;
        const rg = gatherPairs(bpp, 16 * bpp, ri, 1, 1, 0, p);
        const b = gatherPairs(bpp, 16 * bpp, bi, 255, 1, 0, p) | kv;
        const y = (maddv(rg, crg) + maddv(b, cb)) >> @splat(9);
        const s = @min(y + y, spl(32767));
        d[i..][0..16].* = clampU8v((s + spl(64)) >> @splat(7));
    }
    while (i < w) : (i += 1) {
        const r: i32 = row[i * bpp + ri];
        const gg: i32 = row[i * bpp + 1];
        const b: i32 = row[i * bpp + bi];
        const y = (g.ry * r + g.gy * gg + g.by * b + (32 << 14) + (1 << 8)) >> 9;
        d[i] = clip8((@min(y * 2, 32767) + 64) >> 7);
    }
}

pub fn isVIdentity(f: *const Filter, n: usize) bool {
    if (f.size != 1) return false;
    for (0..n) |i| {
        if (f.pos[i] != @as(i32, @intCast(i)) or f.coef[i] != 4096) return false;
    }
    return true;
}
