pub fn isPoint(f: *const Filter, n: usize) bool {
    if (f.size != 1) return false;
    for (0..n) |i| if (f.coef[i] != 16384) return false;
    return true;
}

// gather the source pixels a point-sampling filter reads (pairs when half) into a compact row
pub fn compactPixels(row: [*]const u8, out: [*]u8, f: *const Filter, n: usize, bpp: usize, half: bool) void {
    const pos = f.pos;
    if (half) {
        const step = 2 * bpp;
        for (0..n) |i| {
            const p: usize = @intCast(pos[i]);
            const v = std.mem.readInt(u64, (row + p * step)[0..8], .little);
            std.mem.writeInt(u64, (out + i * step)[0..8], v, .little);
        }
    } else {
        for (0..n) |i| {
            const p: usize = @intCast(pos[i]);
            const v = std.mem.readInt(u32, (row + p * bpp)[0..4], .little);
            std.mem.writeInt(u32, (out + i * bpp)[0..4], v, .little);
        }
    }
}
