const std = @import("std");
const U = @import("unscaled.zig");
test "halfRGB16" {
    var t: U.RgbTables = .{};
    U.initRgbTables(&t, 5);
    var bad: usize = 0;
    var u: i32 = -100;
    while (u <= 400) : (u += 1) {
        var v: i32 = -100;
        while (v <= 400) : (v += 1) {
            const uv: @Vector(8, i32) = @splat(u);
            const vv: @Vector(8, i32) = @splat(v);
            var y0: i32 = -600;
            while (y0 <= 900) : (y0 += 16) {
                var ya: [16]i32 = undefined;
                for (0..16) |k| ya[k] = y0 + @as(i32, @intCast(k));
                const r = U.halfRGB16(ya, uv, vv);
                const ra: [16]u8 = r[0];
                const ga: [16]u8 = r[1];
                const ba: [16]u8 = r[2];
                for (0..16) |k| {
                    const e = U.tableRGB(&t, ya[k], u, v);
                    if (ra[k] != e[0] or ga[k] != e[1] or ba[k] != e[2]) {
                        if (bad < 5) std.debug.print("y{} u{} v{} got {} {} {} exp {any}\n", .{ ya[k], u, v, ra[k], ga[k], ba[k], e });
                        bad += 1;
                    }
                }
            }
        }
    }
    // lane mapping with distinct chroma
    var ul: [8]i32 = undefined;
    var vl: [8]i32 = undefined;
    var ya: [16]i32 = undefined;
    for (0..8) |k| { ul[k] = @as(i32, @intCast(k)) * 37 - 50; vl[k] = 300 - @as(i32, @intCast(k)) * 41; }
    for (0..16) |k| ya[k] = 60 + @as(i32, @intCast(k)) * 9;
    const r = U.halfRGB16(ya, ul, vl);
    const ra: [16]u8 = r[0];
    const ga: [16]u8 = r[1];
    const ba: [16]u8 = r[2];
    for (0..16) |k| {
        const e = U.tableRGB(&t, ya[k], ul[k / 2], vl[k / 2]);
        if (ra[k] != e[0] or ga[k] != e[1] or ba[k] != e[2]) bad += 1;
    }
    try std.testing.expectEqual(@as(usize, 0), bad);
}
