import sys
d=sys.argv[1]
p=d+'/src/simd.zig'
s=open(p).read()
s+='''
pub fn isPoint(f: *const Filter, n: usize) bool {
    if (f.size != 1) return false;
    for (0..n) |i| if (f.coef[i] != 16384) return false;
    return true;
}

pub noinline fn compactPixels(row: [*]const u8, out: [*]u8, f: *const Filter, n: usize, bpp: usize, half: bool, srcW: usize) void {
    const pos = f.pos;
    const rowBytes = srcW * bpp;
    const step = if (half) 2 * bpp else bpp;
    for (0..n) |i| {
        const p: usize = @as(usize, @intCast(pos[i])) * step;
        if (p + 8 <= rowBytes) {
            const v = std.mem.readInt(u64, (row + p)[0..8], .little);
            std.mem.writeInt(u64, (out + i * step)[0..8], v, .little);
        } else {
            for (0..step) |k| out[i * step + k] = row[p + k];
        }
    }
}
'''
