// point-sampled luma with a periodic plan (P = 1): convert only the sampled pixels
pub fn rgbYPointPlan(row: [*]const u8, out: [*]i16, dw: usize, sf: generic.Fmt, g: *const Generic, f: *const Filter, pl: *const HPlan, srcW: usize) bool {
    if (pl.P != 1 or pl.fs != 1 or pl.coef[0][0] != 16384) return false;
    switch (pl.Q) {
        2 => rgbYPointT(2, sf, row, out, dw, g, f, pl, srcW),
        3 => rgbYPointT(3, sf, row, out, dw, g, f, pl, srcW),
        4 => rgbYPointT(4, sf, row, out, dw, g, f, pl, srcW),
        else => return false,
    }
    return true;
}

fn rgbYPointT(comptime Q: usize, sf: generic.Fmt, row: [*]const u8, out: [*]i16, dw: usize, g: *const Generic, f: *const Filter, pl: *const HPlan, srcW: usize) void {
    switch (sf.bpp) {
        3 => if (sf.ri == 0) rgbYPointTT(Q, 3, 0, 2, row, out, dw, g, f, pl, srcW) else rgbYPointTT(Q, 3, 2, 0, row, out, dw, g, f, pl, srcW),
        else => if (sf.ri == 0) rgbYPointTT(Q, 4, 0, 2, row, out, dw, g, f, pl, srcW) else rgbYPointTT(Q, 4, 2, 0, row, out, dw, g, f, pl, srcW),
    }
}

fn rgbYPointTT(comptime Q: usize, comptime bpp: usize, comptime ri: usize, comptime bi: usize, row: [*]const u8, out: [*]i16, dw: usize, g: *const Generic, f: *const Filter, pl: *const HPlan, srcW: usize) void {
    const crg = pairConst(g.ry, g.gy);
    const cb = pairConst(g.by, 16392);
    var bk: [32]i16 = undefined;
    for (0..16) |k| {
        bk[2 * k] = 0;
        bk[2 * k + 1] = 32;
    }
    const kv: V32s = bk;
    const nvec = (pl.m_hi - pl.m_lo) / 16 * 16;
    var m = pl.m_lo;
    while (m < pl.m_lo + nvec) : (m += 16) {
        const p = row + @as(usize, @intCast(pl.base[0] + @as(i32, @intCast(Q * m)))) * bpp;
        const rg = gatherPairs(bpp, 16 * Q * bpp, ri, 1, Q, 0, p);
        const b = gatherPairs(bpp, 16 * Q * bpp, bi, 255, Q, 0, p) | kv;
        const y = (maddv(rg, crg) + maddv(b, cb)) >> @splat(9);
        store16(out + m, @min(y + y, spl(32767)));
    }
    // edges: scalar
    const fill = struct {
        fn run(row_: [*]const u8, out_: [*]i16, f_: *const Filter, a: usize, b_: usize, g_: *const Generic) void {
            for (a..b_) |i| {
                const px: usize = @intCast(f_.pos[i]);
                const r: i32 = row_[px * bpp + ri];
                const gg: i32 = row_[px * bpp + 1];
                const bb: i32 = row_[px * bpp + bi];
                const y = (g_.ry * r + g_.gy * gg + g_.by * bb + (32 << 14) + (1 << 8)) >> 9;
                out_[i] = @intCast(@min(y * 2, 32767));
            }
        }
    }.run;
    fill(row, out, f, 0, pl.m_lo, g);
    fill(row, out, f, pl.m_lo + nvec, dw, g);
    _ = srcW;
}
